import { describe, it, expect } from "vitest";
import * as fc from "fast-check";
import { resolvePostAuthDestination, isSafeRedirectPath, isValidRedirectForRole, defaultDashboardForRole, type AuthRole } from "@/lib/routing";

// Feature: multi-method-auth, Property 6: Post-login redirect resolution is always safe and consistent across methods

describe("resolvePostAuthDestination (Property 6)", () => {
  const roleArb = fc.constantFrom<AuthRole>("customer", "vendor");
  
  // Safe paths: starts with / but not //
  const validPathArb = (role: AuthRole) => fc.oneof(
    fc.string({ minLength: 1 }).map(s => `/public-${s.replace(/[^a-zA-Z0-9-]/g, "")}`),
    fc.string({ minLength: 1 }).map(s => `/messages/${s.replace(/[^a-zA-Z0-9-]/g, "")}`),
    fc.string({ minLength: 1 }).map(s => `/${role}/${s.replace(/[^a-zA-Z0-9-]/g, "")}`)
  );

  const invalidSafePathArb = (role: AuthRole) => {
    const wrongRole = role === "customer" ? "vendor" : "customer";
    return fc.oneof(
      fc.string({ minLength: 1 }).map(s => `/${wrongRole}/${s.replace(/[^a-zA-Z0-9-]/g, "")}`),
      fc.string({ minLength: 1 }).map(s => `/admin/${s.replace(/[^a-zA-Z0-9-]/g, "")}`)
    );
  };

  // Unsafe paths: absolute URLs or starts with // or contains :
  const unsafePathArb = fc.oneof(
    fc.webUrl(),
    fc.string().map(s => `//${s}`),
    fc.string().map(s => `/\\${s}`),
    fc.string().map(s => `javascript:${s}`)
  );

  const planArb = fc.option(fc.string({ minLength: 1 }), { nil: undefined });

  it("returns the safe next path if it is valid for the role", () => {
    fc.assert(
      fc.property(
        roleArb.chain(role => fc.record({ role: fc.constant(role), next: validPathArb(role) })),
        planArb,
        ({ role, next }, plan) => {
          const result = resolvePostAuthDestination(role, next, plan);
          expect(result).toBe(next);
        }
      ),
      { numRuns: 100 }
    );
  });

  it("returns the fallback dashboard if the next path is safe but invalid for the role", () => {
    fc.assert(
      fc.property(
        roleArb.chain(role => fc.record({ role: fc.constant(role), next: invalidSafePathArb(role) })),
        planArb,
        ({ role, next }, plan) => {
          const result = resolvePostAuthDestination(role, next, plan);
          const fallback = defaultDashboardForRole(role, plan);
          expect(result).toBe(fallback);
        }
      ),
      { numRuns: 100 }
    );
  });

  it("returns the fallback dashboard if the next path is unsafe", () => {
    fc.assert(
      fc.property(
        roleArb,
        unsafePathArb,
        planArb,
        (role, next, plan) => {
          const result = resolvePostAuthDestination(role, next, plan);
          const fallback = defaultDashboardForRole(role, plan);
          expect(result).toBe(fallback);
        }
      ),
      { numRuns: 100 }
    );
  });

  it("returns the fallback dashboard if next path is empty or missing", () => {
    fc.assert(
      fc.property(
        roleArb,
        fc.constantFrom("", null, undefined),
        planArb,
        (role, next, plan) => {
          const result = resolvePostAuthDestination(role, next, plan);
          const fallback = defaultDashboardForRole(role, plan);
          expect(result).toBe(fallback);
        }
      ),
      { numRuns: 100 }
    );
  });
});

// @vitest-environment jsdom
// Feature: elite-ui-overhaul, Property 7: Data Table Sort Ordering

/**
 * Property Test: Data Table Sort Ordering
 *
 * For any data table with N rows and for any sortable column, when sort is
 * applied in ascending order, each row's value for that column SHALL be ≤ the
 * next row's value. When sort is applied in descending order, each row's value
 * SHALL be ≥ the next row's value.
 *
 * **Validates: Requirements 8.3, 9.3**
 */

import { describe, it, expect } from "vitest";
import * as fc from "fast-check";
import { render, screen, fireEvent } from "@testing-library/react";
import { PBT_CONFIG } from "./setup";
import { DataTable } from "@/components/data-table";
import type { DataTableColumn } from "@/components/data-table";

// ─── Arbitraries ─────────────────────────────────────────────────────────────

interface TestRow extends Record<string, unknown> {
  name: string;
  age: number;
  city: string;
  score: number;
}

/**
 * Generates a random row of data with string and numeric fields.
 */
const testRowArb: fc.Arbitrary<TestRow> = fc.record({
  name: fc.string({ minLength: 1, maxLength: 20 }).filter((s) => s.trim().length > 0),
  age: fc.integer({ min: 0, max: 120 }),
  city: fc.constantFrom("Perth", "Sydney", "Melbourne", "Brisbane", "Adelaide"),
  score: fc.integer({ min: 0, max: 1000 }),
});

/**
 * Generates a non-empty array of test rows (1 to 50 rows).
 * We keep it reasonable for rendering performance.
 */
const testDataArb: fc.Arbitrary<TestRow[]> = fc.array(testRowArb, {
  minLength: 1,
  maxLength: 50,
});

/**
 * Generates a sortable column key from the available columns.
 */
const sortableColumnKeyArb: fc.Arbitrary<keyof TestRow> = fc.constantFrom(
  "name",
  "age",
  "city",
  "score"
);

// ─── Test Columns Definition ─────────────────────────────────────────────────

const TEST_COLUMNS: DataTableColumn<TestRow>[] = [
  { key: "name", label: "Name", sortable: true },
  { key: "age", label: "Age", sortable: true },
  { key: "city", label: "City", sortable: true },
  { key: "score", label: "Score", sortable: true },
];

// ─── Helper: Extract cell values from rendered table ─────────────────────────

function getColumnValues(container: HTMLElement, columnIndex: number): string[] {
  const rows = container.querySelectorAll("tbody tr");
  const values: string[] = [];
  rows.forEach((row) => {
    const cells = row.querySelectorAll("td");
    if (cells[columnIndex]) {
      values.push(cells[columnIndex].textContent || "");
    }
  });
  return values;
}

/**
 * Checks that string values are in ascending order using localeCompare.
 */
function isAscendingStrings(values: string[]): boolean {
  for (let i = 0; i < values.length - 1; i++) {
    if (values[i].localeCompare(values[i + 1]) > 0) {
      return false;
    }
  }
  return true;
}

/**
 * Checks that string values are in descending order using localeCompare.
 */
function isDescendingStrings(values: string[]): boolean {
  for (let i = 0; i < values.length - 1; i++) {
    if (values[i].localeCompare(values[i + 1]) < 0) {
      return false;
    }
  }
  return true;
}

/**
 * Checks that numeric values are in ascending order.
 */
function isAscendingNumbers(values: number[]): boolean {
  for (let i = 0; i < values.length - 1; i++) {
    if (values[i] > values[i + 1]) {
      return false;
    }
  }
  return true;
}

/**
 * Checks that numeric values are in descending order.
 */
function isDescendingNumbers(values: number[]): boolean {
  for (let i = 0; i < values.length - 1; i++) {
    if (values[i] < values[i + 1]) {
      return false;
    }
  }
  return true;
}

// ─── Property Tests ──────────────────────────────────────────────────────────

describe("Property 7: Data Table Sort Ordering", () => {
  it("ascending sort ensures each value ≤ next for any data array and sortable column", () => {
    fc.assert(
      fc.property(testDataArb, sortableColumnKeyArb, (data, columnKey) => {
        const columnIndex = TEST_COLUMNS.findIndex((c) => c.key === columnKey);

        // Render with a large page size to show all rows without pagination
        const { container, unmount } = render(
          <DataTable
            columns={TEST_COLUMNS}
            data={data}
            pageSize={data.length}
          />
        );

        // Click the sortable column header to trigger ascending sort
        const headerCells = container.querySelectorAll("th");
        fireEvent.click(headerCells[columnIndex]);

        // Extract column values from the rendered table
        const values = getColumnValues(container, columnIndex);

        // Verify ascending order
        if (columnKey === "age" || columnKey === "score") {
          // Numeric columns
          const numericValues = values.map(Number);
          expect(isAscendingNumbers(numericValues)).toBe(true);
        } else {
          // String columns
          expect(isAscendingStrings(values)).toBe(true);
        }

        unmount();
      }),
      PBT_CONFIG
    );
  }, 20000);

  it("descending sort ensures each value ≥ next for any data array and sortable column", () => {
    fc.assert(
      fc.property(testDataArb, sortableColumnKeyArb, (data, columnKey) => {
        const columnIndex = TEST_COLUMNS.findIndex((c) => c.key === columnKey);

        // Render with a large page size to show all rows without pagination
        const { container, unmount } = render(
          <DataTable
            columns={TEST_COLUMNS}
            data={data}
            pageSize={data.length}
          />
        );

        // Click header once for ascending, then again for descending
        const headerCells = container.querySelectorAll("th");
        fireEvent.click(headerCells[columnIndex]); // ascending
        fireEvent.click(headerCells[columnIndex]); // descending

        // Extract column values from the rendered table
        const values = getColumnValues(container, columnIndex);

        // Verify descending order
        if (columnKey === "age" || columnKey === "score") {
          // Numeric columns
          const numericValues = values.map(Number);
          expect(isDescendingNumbers(numericValues)).toBe(true);
        } else {
          // String columns
          expect(isDescendingStrings(values)).toBe(true);
        }

        unmount();
      }),
      PBT_CONFIG
    );
  }, 20000);
});

// Feature: mobile-optimisation, Task 12.1: Mobile animation constraints

/**
 * Unit tests for mobile animation governance.
 *
 * Covers:
 *  - clampAnimationDuration caps mobile durations at 300ms (Req 11.4)
 *  - MobileAnimationProvider limits concurrent animations to 3 on mobile (Req 11.3)
 *  - reduced-motion preference is surfaced through the context (Req 11.2)
 *  - desktop viewports are not concurrency-capped
 */

// @vitest-environment jsdom

import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import { renderHook, act } from "@testing-library/react";
import {
  MobileAnimationProvider,
  useMobileAnimation,
  clampAnimationDuration,
  MAX_CONCURRENT_MOBILE_ANIMATIONS,
  MOBILE_MAX_ANIMATION_DURATION,
} from "@/components/mobile-animation-provider";

/**
 * Install a matchMedia mock. `mobile` controls whether the mobile-width query
 * matches; `reducedMotion` controls the reduced-motion query.
 */
function installMatchMedia(opts: { mobile: boolean; reducedMotion: boolean }) {
  const listeners = new Set<(e: MediaQueryListEvent) => void>();
  window.matchMedia = vi.fn().mockImplementation((query: string) => {
    const matches = query.includes("max-width")
      ? opts.mobile
      : query.includes("prefers-reduced-motion")
        ? opts.reducedMotion
        : false;
    return {
      matches,
      media: query,
      onchange: null,
      addEventListener: (_: string, cb: (e: MediaQueryListEvent) => void) =>
        listeners.add(cb),
      removeEventListener: (_: string, cb: (e: MediaQueryListEvent) => void) =>
        listeners.delete(cb),
      addListener: () => {},
      removeListener: () => {},
      dispatchEvent: () => false,
    } as unknown as MediaQueryList;
  });
}

describe("clampAnimationDuration (Req 11.4)", () => {
  it("passes desktop durations through unchanged", () => {
    expect(clampAnimationDuration(0.8, false)).toBe(0.8);
    expect(clampAnimationDuration(0.6, false)).toBe(0.6);
    expect(clampAnimationDuration(0.1, false)).toBe(0.1);
  });

  it("caps mobile durations at 300ms", () => {
    expect(clampAnimationDuration(0.8, true)).toBe(MOBILE_MAX_ANIMATION_DURATION);
    expect(clampAnimationDuration(0.6, true)).toBe(MOBILE_MAX_ANIMATION_DURATION);
    expect(clampAnimationDuration(0.3, true)).toBe(0.3);
  });

  it("does not raise durations already below the mobile cap", () => {
    expect(clampAnimationDuration(0.2, true)).toBe(0.2);
  });

  it("floors negative durations at 0", () => {
    expect(clampAnimationDuration(-1, true)).toBe(0);
    expect(clampAnimationDuration(-1, false)).toBe(0);
  });
});

describe("MobileAnimationProvider concurrency governance (Req 11.3)", () => {
  const originalMatchMedia = window.matchMedia;

  afterEach(() => {
    window.matchMedia = originalMatchMedia;
  });

  it("limits concurrent animations to 3 on mobile", () => {
    installMatchMedia({ mobile: true, reducedMotion: false });

    const { result } = renderHook(() => useMobileAnimation(), {
      wrapper: MobileAnimationProvider,
    });

    expect(result.current.isMobile).toBe(true);
    expect(result.current.maxConcurrent).toBe(MAX_CONCURRENT_MOBILE_ANIMATIONS);

    // First three acquisitions succeed.
    act(() => {
      expect(result.current.acquireSlot()).toBe(true);
      expect(result.current.acquireSlot()).toBe(true);
      expect(result.current.acquireSlot()).toBe(true);
    });

    // The fourth is rejected — the cap has been reached.
    act(() => {
      expect(result.current.acquireSlot()).toBe(false);
    });

    // Releasing one frees a slot for the next acquisition.
    act(() => {
      result.current.releaseSlot();
      expect(result.current.acquireSlot()).toBe(true);
      expect(result.current.acquireSlot()).toBe(false);
    });
  });

  it("does not cap concurrency on desktop viewports", () => {
    installMatchMedia({ mobile: false, reducedMotion: false });

    const { result } = renderHook(() => useMobileAnimation(), {
      wrapper: MobileAnimationProvider,
    });

    expect(result.current.isMobile).toBe(false);

    act(() => {
      for (let i = 0; i < 20; i++) {
        expect(result.current.acquireSlot()).toBe(true);
      }
    });
  });

  it("surfaces the reduced-motion preference (Req 11.2)", () => {
    installMatchMedia({ mobile: true, reducedMotion: true });

    const { result } = renderHook(() => useMobileAnimation(), {
      wrapper: MobileAnimationProvider,
    });

    expect(result.current.prefersReducedMotion).toBe(true);
  });
});

describe("useMobileAnimation default (outside a provider)", () => {
  it("degrades gracefully to always-animate", () => {
    const { result } = renderHook(() => useMobileAnimation());
    expect(result.current.acquireSlot()).toBe(true);
    expect(result.current.prefersReducedMotion).toBe(false);
    // releaseSlot must be a no-op that does not throw.
    expect(() => result.current.releaseSlot()).not.toThrow();
  });
});

// Feature: elite-ui-overhaul, Property 3: VehicleCard Field Completeness

/**
 * Property Test: VehicleCard Field Completeness
 *
 * For any valid Vehicle object, rendered VehicleCard SHALL contain
 * vehicle name, category, price per day, vendor name, location city,
 * and a CTA link to the vehicle detail page.
 *
 * **Validates: Requirements 5.5**
 */

// @vitest-environment jsdom

import { describe, it, expect, vi } from "vitest";
import * as fc from "fast-check";
import { render } from "@testing-library/react";
import { PBT_CONFIG } from "./setup";
import { vehicleArb } from "./arbitraries";
import type { Vehicle as ArbVehicle } from "./arbitraries";
import { VehicleCard } from "@/components/vehicle-card";
import type { Vehicle } from "@/lib/types";

// Mock next/image to render a plain img element
vi.mock("next/image", () => ({
  default: (props: Record<string, unknown>) => {
    const { fill, priority, sizes, ...rest } = props;
    return <img {...(rest as React.ImgHTMLAttributes<HTMLImageElement>)} />;
  },
}));

// Mock next/link to render a plain anchor
vi.mock("next/link", () => ({
  default: ({
    href,
    children,
    ...props
  }: {
    href: string;
    children: React.ReactNode;
    [key: string]: unknown;
  }) => (
    <a href={href} {...props}>
      {children}
    </a>
  ),
}));

/**
 * Maps the generated arbitrary Vehicle (design doc shape) to the
 * component's Vehicle type (from @/lib/types).
 */
function toComponentVehicle(arb: ArbVehicle): Vehicle {
  return {
    id: arb.id,
    slug: arb.slug,
    title: arb.name,
    make: "TestMake",
    model: "TestModel",
    year: 2023,
    city: arb.location_city,
    state: "WA",
    pricePerDayAud: arb.price_per_day,
    seats: arb.seats,
    fuel: arb.fuel_type,
    transmission: arb.transmission,
    category: arb.category,
    imageUrl: arb.image_url || "/vehicle-placeholder.jpg",
    vendorName: arb.vendor_name,
    vendorSlug: arb.vendor_slug,
    branchName: arb.branch_location,
    verified: true,
    instantBook: false,
  };
}

const baseVehicle: Vehicle = {
  id: "11111111-1111-1111-1111-111111111111",
  slug: "test-car",
  title: "2023 Test Car",
  make: "Test",
  model: "Car",
  year: 2023,
  city: "Sydney",
  state: "NSW",
  pricePerDayAud: 45,
  seats: 5,
  fuel: "Petrol",
  transmission: "Automatic",
  category: "Sedan",
  imageUrl: "/vehicle-placeholder.jpg",
  vendorName: "Acme Rentals",
  vendorSlug: "acme",
  branchName: "Sydney CBD",
  verified: true,
};

describe("VehicleCard enrichment field gating", () => {
  it("hides rating, weekly/monthly, logo, Super Host and chips when their data is absent", () => {
    const { container, unmount } = render(<VehicleCard vehicle={{ ...baseVehicle, dailyDistanceLimitKm: 200 }} />);
    const text = container.textContent || "";
    expect(text).not.toContain("Reviews");
    expect(text).not.toContain("Weekly from");
    expect(text).not.toContain("Super Host");
    expect(text).not.toContain("Free cancellation");
    expect(text).not.toContain("No hidden fees");
    expect(text).not.toContain("Free delivery");
    expect(text).not.toContain("Unlimited km"); // KM limit set => not unlimited
    expect(container.querySelector("img[alt='Acme Rentals']")).toBeNull(); // no logo
    unmount();
  });

  it("shows rating, weekly/monthly, logo, Super Host, delivery and chips when present", () => {
    const vehicle: Vehicle = {
      ...baseVehicle,
      avgRating: 4.9,
      reviewCount: 38,
      weeklyRateAud: 210,
      monthlyRateAud: 800,
      vendorLogoUrl: "https://example.supabase.co/logo.png",
      superHost: true,
      features: ["Air Conditioning"],
      freeDelivery: true,
      freeCancellation: true,
      noHiddenFees: true,
      dailyDistanceLimitKm: null, // unlimited
    };
    const { container, unmount } = render(<VehicleCard vehicle={vehicle} variant="featured" />);
    const text = container.textContent || "";
    expect(text).toContain("(38 Reviews)");
    expect(text).toContain("Weekly from");
    expect(text).toContain("210");
    expect(text).toContain("Monthly from");
    expect(text).toContain("Super Host");
    expect(text).toContain("Air Conditioning");
    expect(text).toContain("Free delivery available");
    expect(text).toContain("Free cancellation");
    expect(text).toContain("No hidden fees");
    expect(text).toContain("Unlimited km");
    expect(text).toContain("Featured");
    expect(container.querySelector("img[alt='Acme Rentals']")).not.toBeNull();
    unmount();
  });
});

describe("Property 3: VehicleCard Field Completeness", () => {
  it("rendered VehicleCard contains vehicle name, category, price, vendor name, location city, and CTA link for any valid Vehicle", () => {
    fc.assert(
      fc.property(vehicleArb, (arbVehicle) => {
        const vehicle = toComponentVehicle(arbVehicle);
        const { container, unmount } = render(<VehicleCard vehicle={vehicle} />);

        const textContent = container.textContent || "";

        // Vehicle name must be present
        expect(textContent).toContain(vehicle.title);

        // Price per day must be present (as rendered number)
        expect(textContent).toContain(String(vehicle.pricePerDayAud));

        // Vendor name must be present
        expect(textContent).toContain(vehicle.vendorName);

        // Location city must be present
        expect(textContent).toContain(vehicle.city);

        // CTA link to vehicle detail page must be present
        const link = container.querySelector(`a[href="/cars/${vehicle.slug}"]`);
        expect(link).not.toBeNull();

        // Cleanup to avoid DOM accumulation
        unmount();
      }),
      PBT_CONFIG
    );
  });
});

"use client";

import Link from "next/link";
import Image from "next/image";
import { motion, useScroll, useTransform } from "framer-motion";
import { Building2, ShieldCheck, HeartHandshake, ArrowRight, Zap, Car, Lock, Globe, AlertCircle, DollarSign } from "lucide-react";
import { useRef } from "react";
import { SiteHeader } from "@/components/site-header";
import { SiteFooter } from "@/components/site-footer";

export function AboutClient() {
  const containerRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start start", "end end"]
  });

  // Parallax effects
  const yHero = useTransform(scrollYProgress, [0, 1], ["0%", "50%"]);
  const opacityHero = useTransform(scrollYProgress, [0, 0.2], [1, 0]);

  return (
    <div ref={containerRef} className="min-h-screen bg-slate-950 text-slate-50 selection:bg-orange-500/30 selection:text-orange-200">
      <SiteHeader />

      <main className="relative z-10 overflow-hidden">
        {/* SECTION 1: Artistic Hero */}
        <section className="relative min-h-[90vh] flex items-center justify-center pt-20 pb-32 px-4 sm:px-6 lg:px-8">
          {/* Animated Background Orbs */}
          <div className="absolute inset-0 overflow-hidden pointer-events-none">
            <motion.div 
              animate={{ 
                scale: [1, 1.2, 1],
                opacity: [0.3, 0.5, 0.3],
                rotate: [0, 90, 0]
              }}
              transition={{ duration: 20, repeat: Infinity, ease: "linear" }}
              className="absolute -top-[20%] -left-[10%] w-[70vw] h-[70vw] rounded-full bg-gradient-to-br from-orange-600/30 to-amber-500/10 blur-[120px]"
            />
            <motion.div 
              animate={{ 
                scale: [1, 1.5, 1],
                opacity: [0.2, 0.4, 0.2],
                rotate: [0, -90, 0]
              }}
              transition={{ duration: 25, repeat: Infinity, ease: "linear" }}
              className="absolute top-[40%] -right-[20%] w-[60vw] h-[60vw] rounded-full bg-gradient-to-tl from-slate-600/30 to-slate-800/10 blur-[100px]"
            />
            <div className="absolute inset-0 bg-[url('/noise.png')] opacity-20 mix-blend-overlay"></div>
          </div>

          <motion.div 
            style={{ y: yHero, opacity: opacityHero }}
            className="relative z-10 max-w-5xl mx-auto text-center"
          >
            <motion.div
              initial={{ opacity: 0, y: 30 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.8, delay: 0.2 }}
            >
              <h2 className="text-orange-500 font-bold tracking-widest uppercase text-sm mb-6 flex items-center justify-center gap-2">
                <span className="h-px w-8 bg-orange-500"></span>
                Our Mission
                <span className="h-px w-8 bg-orange-500"></span>
              </h2>
            </motion.div>
            
            <motion.h1 
              className="text-5xl sm:text-7xl lg:text-8xl font-black tracking-tight mb-8 leading-[1.1]"
              initial={{ opacity: 0, y: 40 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.8, delay: 0.3 }}
            >
              Solving the <span className="text-transparent bg-clip-text bg-gradient-to-r from-orange-400 via-amber-500 to-orange-600">rental monopoly.</span>
            </motion.h1>
            
            <motion.p 
              className="text-xl sm:text-2xl text-slate-400 max-w-3xl mx-auto font-medium leading-relaxed"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ duration: 0.8, delay: 0.5 }}
            >
              We are dismantling the outdated car rental industry, giving power back to local operators and putting customers directly in the driver&apos;s seat.
            </motion.p>
          </motion.div>

          <motion.div 
            className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2 text-slate-500"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 1.5, duration: 1 }}
          >
            <span className="text-xs uppercase tracking-widest font-bold">Discover the problem</span>
            <motion.div 
              animate={{ y: [0, 8, 0] }} 
              transition={{ duration: 2, repeat: Infinity }}
              className="w-[1px] h-12 bg-gradient-to-b from-orange-500 to-transparent"
            />
          </motion.div>
        </section>

        {/* SECTION 2: The Problem (Dark Mode Sticky Scroll) */}
