});

export async function updateFraudFlagStatus(rawAction: string, rawFlagId: string) {
  const user = await requireAdminRole(["moderator", "super_admin"]);
  const supabase = createAdminClient();

  const { action, flagId } = UpdateFraudFlagStatusSchema.parse({
    action: rawAction,
    flagId: rawFlagId,
  });

  const isClosing = action === "close";

  const { error } = await supabase
    .from("fraud_flags")
    .update({
      status: isClosing ? "closed" : "open",
      reviewed_by: isClosing ? user.id : null,
      reviewed_at: isClosing ? new Date().toISOString() : null,
    })
    .eq("id", flagId);

  if (error) {
    throw new Error(`Failed to ${action} flag: ${error.message}`);
  }

  // Add moderation note
  await supabase.from("moderation_notes").insert({
    resource_type: "fraud_flag",
    resource_id: flagId,
    author_user_id: user.id,
    body: isClosing
      ? "[CLOSED] Fraud flag investigated and closed"
      : "[REOPENED] Fraud flag reopened for further review",
  });

  // Log audit event
  await supabase.from("audit_logs").insert({
    actor_user_id: user.id,
    action: isClosing ? "fraud_flag_closed" : "fraud_flag_reopened",
    resource_type: "fraud_flag",
    resource_id: flagId,
  });

  revalidatePath("/admin/fraud");
  revalidatePath("/admin");
}

export async function transferBranchAction(formData: FormData) {
  const user = await requireAdminRole(["super_admin", "moderator"]);
  const supabase = createAdminClient();

  const parsed = transferBranchSchema.safeParse({
    branchId: formData.get("branchId"),
    email: formData.get("email"),
    businessName: formData.get("businessName"),
    abn: formData.get("abn"),
    phone: formData.get("phone") || "",
    address: formData.get("address") || "",
    website: formData.get("website") || "",
    approveImmediately: formData.get("approveImmediately") === "on" || formData.get("approveImmediately") === "true",
  });

  if (!parsed.success) {
    const errorMessages = parsed.error.issues.map((i) => i.message).join(", ");
    return { error: `Invalid form data: ${errorMessages}` };
  }

  const payload = parsed.data;

  try {
    // Get branch details for email
    const { data: branchCheck, error: branchCheckError } = await supabase
      .from("branches")
      .select("id, name, organizations!inner(name)")
      .eq("id", payload.branchId)
      .single();

    if (branchCheckError || !branchCheck) {
      return { error: "Branch not found." };
    }

    // Check if profile exists by email
    const { data: existingProfile } = await supabase
      .from("profiles")
      .select("id")
      .eq("email", payload.email)
      .single();

    let targetUserId = existingProfile?.id;

    if (!targetUserId) {
      // Invite new user
      const { data: authData, error: inviteError } = await supabase.auth.admin.inviteUserByEmail(payload.email, {
        data: { full_name: payload.businessName },
      });

      if (inviteError || !authData.user) {
        return { error: inviteError?.message || "Failed to invite user" };
      }
      
      targetUserId = authData.user.id;
      
      // Create their profile
      await supabase.from("profiles").upsert({
        id: targetUserId,
        email: payload.email,
        full_name: payload.businessName,
        phone: payload.phone || null,
      });
    }

    // Create new organization
    const orgSlug = uniqueSlug(payload.businessName);
    
    const { data: organization, error: orgError } = await supabase
      .from("organizations")
      .insert({
        name: payload.businessName,
        slug: orgSlug,
        abn: payload.abn,
        billing_email: payload.email,
        website: payload.website || null,
        phone: payload.phone || null,
        address: payload.address || null,
        status: payload.approveImmediately ? "approved" : "pending",
      })
      .select("id")
      .single();

    if (orgError || !organization) {
      return { error: orgError?.message || "Failed to create organization" };
    }

    // Add owner to organization
    await supabase.from("organization_members").insert({
      organization_id: organization.id,
      user_id: targetUserId,
      role: "owner",
    });

    // Re-assign branch
    const { error: branchError } = await supabase
      .from("branches")
      .update({ 
        organization_id: organization.id,
        status: payload.approveImmediately ? "approved" : "pending",
        updated_at: new Date().toISOString()
      })
      .eq("id", payload.branchId);

    if (branchError) {
      return { error: branchError.message };
    }

    // Transfer associated vehicles to the new organization
    const { data: transferredVehicles, error: vehiclesError } = await supabase
      .from("vehicles")
      .update({ organization_id: organization.id })
      .eq("branch_id", payload.branchId)
      .select("id");

    if (vehiclesError) {
      return { error: "Branch was transferred, but failed to re-assign associated vehicles: " + vehiclesError.message };
    }

    // Enqueue search index jobs for the transferred vehicles so they show up under the new vendor
    if (transferredVehicles && transferredVehicles.length > 0) {
      const jobs = transferredVehicles.map(v => ({
        vehicle_id: v.id,
        operation: "upsert",
        status: "pending"
      }));
      await supabase.from("search_index_jobs").insert(jobs);
    }

    // Log audit event
    await supabase.from("audit_logs").insert({
      actor_user_id: user.id,
      action: "branch_transferred",
      resource_type: "branch",
      resource_id: payload.branchId,
      metadata: { 
        previous_org_transferred_from: true,
        new_org_id: organization.id,
        new_owner: payload.email,
        vehicles_transferred: transferredVehicles?.length || 0
      },
    });

    // Send Email Notifications
    const branchName = branchCheck.name;
    const vendorName = (branchCheck.organizations as unknown as { name: string }).name;

    await Promise.allSettled([
      sendBranchTransferInitiatedEmail({
        to: user.email!,
        vendorName: vendorName,
        branchName: branchName,
        newOwnerEmail: payload.email,
        newBusinessName: payload.businessName,
      }),
      sendBranchTransferReceivedEmail({
        to: payload.email,
        newBusinessName: payload.businessName,
        branchName: branchName,
      }),
    ]);

    revalidatePath("/admin/branches");
    revalidatePath("/admin/vendors");
    
    return { success: true };
  } catch (err: any) {
    console.error("Transfer branch error:", err);
    return { error: err.message || "An unexpected error occurred during transfer." };
  }
}

"use client";

import { useActionState, useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { updateBlogArticle, uploadBlogImage, type UpdateBlogArticleState } from "./actions";
import type { AdminBlogArticleDetail } from "@/lib/blog/queries";
import dynamic from "next/dynamic";
import "ckeditor5/ckeditor5.css";

const RichTextEditor = dynamic(() => import("@/components/ui/rich-text-editor"), { ssr: false });


const initialState: UpdateBlogArticleState = { success: false };

interface BlogEditFormProps {
  article: AdminBlogArticleDetail;
  categories: { id: string; name: string; slug: string }[];
  cancelHref: string;
}

export function BlogEditForm({ article, categories, cancelHref }: BlogEditFormProps) {
  const updateWithId = updateBlogArticle.bind(null, article.id);
  const [state, formAction, pending] = useActionState(updateWithId, initialState);
  const prevSuccessRef = useRef(false);
  const [featuredImageUrl, setFeaturedImageUrl] = useState(article.featured_image_url ?? "");
  const [isUploadingImage, setIsUploadingImage] = useState(false);
  const [bodyContent, setBodyContent] = useState(article.body ?? "");

  useEffect(() => {
    if (state.success && !prevSuccessRef.current) {
      toast.success("Article saved.");
    }
    prevSuccessRef.current = state.success;
  }, [state.success]);

  useEffect(() => {
    if (state.error) {
      toast.error(state.error);
    }
  }, [state.error]);

  return (
    <form action={formAction} className="space-y-6">
      <Card variant="elevated">
        <CardHeader>
          <CardTitle>Edit Article</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <Label htmlFor="title">Title</Label>
            <Input id="title" name="title" defaultValue={article.title} className="mt-1" />
            <FieldError errors={state.fieldErrors} field="title" />
          </div>

          <div>
            <Label htmlFor="slug">Slug</Label>
            <Input id="slug" name="slug" defaultValue={article.slug} className="mt-1" />
            <p className="mt-1 text-xs text-muted-foreground">
              Changing the slug moves the article to a new URL — old links will 404.
            </p>
            <FieldError errors={state.fieldErrors} field="slug" />
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <div>
              <Label htmlFor="status">Status</Label>
              <select
                id="status"
                name="status"
                defaultValue={article.status}
                className="mt-1 block w-full rounded-lg border border-input bg-transparent px-3 py-2 text-sm focus:outline-none focus-visible:ring-3 focus-visible:ring-ring/50"
              >
                <option value="draft">Draft</option>
                <option value="published">Published</option>
                <option value="archived">Archived</option>
              </select>
              <FieldError errors={state.fieldErrors} field="status" />
            </div>

            <div>
              <Label htmlFor="categoryId">Category</Label>
              <select
                id="categoryId"
                name="categoryId"
                defaultValue={article.category_id ?? ""}
                className="mt-1 block w-full rounded-lg border border-input bg-transparent px-3 py-2 text-sm focus:outline-none focus-visible:ring-3 focus-visible:ring-ring/50"
              >
                <option value="">— None —</option>
                {categories.map((category) => (
                  <option key={category.id} value={category.id}>
                    {category.name}
                  </option>
                ))}
              </select>
              <FieldError errors={state.fieldErrors} field="categoryId" />
            </div>
          </div>

          <div>
            <Label htmlFor="excerpt">Excerpt</Label>
            <Textarea
              id="excerpt"
              name="excerpt"
              rows={2}
              defaultValue={article.excerpt}
              className="mt-1"
            />
            <FieldError errors={state.fieldErrors} field="excerpt" />
          </div>

          <div>
            <Label htmlFor="body">Body (HTML)</Label>
            <div className="mt-1">
              <RichTextEditor value={bodyContent} onChange={setBodyContent} />
              <input type="hidden" name="body" value={bodyContent} />
            </div>
            <p className="mt-1 text-xs text-muted-foreground">
              Rich text editor enabled. Custom styles, images, and embedded media are supported.
            </p>
            <FieldError errors={state.fieldErrors} field="body" />
          </div>
        </CardContent>
      </Card>

      <Card variant="elevated">
        <CardHeader>
          <CardTitle>SEO &amp; Media</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-2">
            <div>
              <Label htmlFor="featuredImageUrl">Featured Image</Label>
              <div className="mt-1 flex flex-col gap-2">
                <div className="flex gap-2">
                  <Input
                    id="featuredImageUrl"
                    name="featuredImageUrl"
                    value={featuredImageUrl}
                    onChange={(e) => setFeaturedImageUrl(e.target.value)}
                    className="flex-1"
                    placeholder="https://..."
                  />
                  <div className="relative">
                    <input
                      type="file"
                      accept="image/jpeg,image/png,image/webp"
                      className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                      title="Upload custom image"
                      disabled={isUploadingImage}
                      onChange={async (e) => {
                        const file = e.target.files?.[0];
                        if (!file) return;
                        setIsUploadingImage(true);
                        try {
                          const formData = new FormData();
                          formData.append("file", file);
                          formData.append("slug", article.slug);
                          const res = await uploadBlogImage(formData);
                          if (res.success) {
                            setFeaturedImageUrl(res.url);
                            toast.success("Image uploaded!");
                          } else {
                            toast.error(res.error);
                          }
                        } catch (err) {
                          toast.error("Failed to upload image");
                        } finally {
                          setIsUploadingImage(false);
                          e.target.value = "";
                        }
                      }}
                    />
                    <button
                      type="button"
                      disabled={isUploadingImage}
                      className="whitespace-nowrap rounded-lg border border-input bg-background px-4 py-2 text-sm font-medium hover:bg-accent hover:text-accent-foreground disabled:opacity-50"
                    >
                      {isUploadingImage ? "Uploading..." : "Upload File"}
                    </button>
                  </div>
                </div>
                {featuredImageUrl && (
                  <div className="relative aspect-video w-full max-w-xs overflow-hidden rounded-lg border border-border mt-2 bg-slate-100">
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    <img src={featuredImageUrl} alt="Preview" className="object-cover w-full h-full" />
                  </div>
                )}
              </div>
              <FieldError errors={state.fieldErrors} field="featuredImageUrl" />
            </div>
            <div>
              <Label htmlFor="featuredImageAlt">Featured Image Alt Text</Label>
              <Input
                id="featuredImageAlt"
                name="featuredImageAlt"
                defaultValue={article.featured_image_alt ?? ""}
                className="mt-1"
              />
              <FieldError errors={state.fieldErrors} field="featuredImageAlt" />
            </div>
          </div>

          <div>
            <Label htmlFor="metaTitle">Meta Title</Label>
            <Input
              id="metaTitle"
              name="metaTitle"
              defaultValue={article.meta_title ?? ""}
              className="mt-1"
            />
            <FieldError errors={state.fieldErrors} field="metaTitle" />
          </div>

          <div>
            <Label htmlFor="metaDescription">Meta Description</Label>
            <Textarea
              id="metaDescription"
              name="metaDescription"
              rows={2}
              defaultValue={article.meta_description ?? ""}
              className="mt-1"
            />
            <FieldError errors={state.fieldErrors} field="metaDescription" />
          </div>

          <div>
            <Label htmlFor="tags">Tags (comma-separated)</Label>
            <Input
              id="tags"
              name="tags"
              defaultValue={article.tags.join(", ")}
              className="mt-1"
            />
            <FieldError errors={state.fieldErrors} field="tags" />
          </div>
        </CardContent>
      </Card>

      <div className="flex items-center justify-end gap-3">
        <a
          href={cancelHref}
          className="rounded-lg border border-border px-4 py-2 text-sm font-medium text-foreground hover:bg-muted transition-colors"
        >
          Cancel
        </a>
        <button
          type="submit"
          disabled={pending}
          className="inline-flex items-center gap-2 rounded-lg bg-primary px-5 py-2.5 text-sm font-medium text-primary-foreground shadow-sm hover:bg-primary/90 focus:outline-none focus:ring-2 focus:ring-primary/50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          {pending ? "Saving…" : "Save Article"}
        </button>
      </div>
    </form>
  );
}

function FieldError({
  errors,
  field,
}: {
  errors?: Record<string, string[]>;
  field: string;
}) {
  const fieldErrors = errors?.[field];
  if (!fieldErrors?.length) return null;
  return (
    <p className="mt-1 text-xs text-red-600 dark:text-red-400" aria-live="polite">
      {fieldErrors.join(", ")}
    </p>
  );
}

"use client";

import { useState, useMemo } from "react";
import { DataTable, type DataTableColumn } from "@/components/data-table";
