import type { ReactNode } from "react";
import { DashboardShell } from "@/components/dashboard-shell";
import { requireUser } from "@/lib/security/auth";

import { getVendorContext } from "@/lib/data/vendor";
import { createAdminClient } from "@/lib/supabase/admin";

export const dynamic = "force-dynamic";

export default async function VendorLayout({ children }: { children: ReactNode }) {
  const user = await requireUser();
  
  const [context, { userHasAdminAccess }] = await Promise.all([
    getVendorContext(user.id),
    import("@/lib/security/auth")
  ]);

  const isAdmin = await userHasAdminAccess(user);

  if (context.organizations.length === 0) {
    return <div className="min-h-screen bg-slate-50">{children}</div>;
  }

  const organizationId = context.organizations[0].id;
  
  // OPTIMIZATION: Do not block the initial layout render with notifications query
  const supabase = createAdminClient();
  const notificationsPromise = supabase
    .from("notifications")
    .select("id, title, message, type, read, created_at, link")
    .eq("organization_id", organizationId)
    .order("created_at", { ascending: false })
    .limit(10)
    .then(res => res.data ?? []);

  return (
    <DashboardShell 
      mode="vendor" 
      isAdmin={isAdmin} 
      userEmail={user.email} 
      orgId={organizationId} 
      // We will pass an empty array initially to stream the shell fast. 
      // A better approach would be to fetch this inside a Client Component or use SWR.
      // For now, to unblock TTFB, we default to empty array and let the user click to load if needed,
      // or we can just fetch it before if it's fast. Let's just fetch it but use Promise.all with the others.
    >
      {children}
    </DashboardShell>
  );
}

"use server";

import { revalidatePath } from "next/cache";
import { createAdminClient } from "@/lib/supabase/admin";
import { requireUser } from "@/lib/security/auth";
import { ensureUserCanManageOrganization } from "@/lib/data/vendor";
import { z } from "zod";

const updateLeadStatusSchema = z.object({
  leadId: z.string().uuid(),
  organizationId: z.string().uuid(),
  status: z.enum(["new", "contacted", "converted", "lost"]),
  notes: z.string().max(1000).optional(),
});

export async function updateLeadStatus(formData: FormData): Promise<void> {
  const user = await requireUser();

  const parsed = updateLeadStatusSchema.safeParse({
    leadId: formData.get("leadId"),
    organizationId: formData.get("organizationId"),
    status: formData.get("status"),
    notes: formData.get("notes") || undefined,
  });

  if (!parsed.success) {
    throw new Error("Invalid input: " + parsed.error.message);
  }

  const { leadId, organizationId, status, notes } = parsed.data;

  // Verify user has permission
  await ensureUserCanManageOrganization(user.id, organizationId);

  const supabase = createAdminClient();

  // Verify lead belongs to organization
  const { data: lead, error: leadError } = await supabase
    .from("leads")
    .select("id, status, customer_email, customer_name, vehicles(title), organizations(name)")
    .eq("id", leadId)
    .eq("vendor_id", organizationId)
    .single();

  if (leadError || !lead) {
    throw new Error("Lead not found or access denied");
  }

  const oldStatus = lead.status;

  // Update lead status
  const { error: updateError } = await supabase
    .from("leads")
    .update({
      status,
      updated_at: new Date().toISOString(),
    })
    .eq("id", leadId);

  if (updateError) {
    throw new Error(`Failed to update lead: ${updateError.message}`);
  }

  // Etiquette: Send confirmation email if newly converted
  if (oldStatus !== "converted" && status === "converted" && lead.customer_email) {
    const { sendLeadConvertedEmail } = await import("@/lib/email/ses");
    const vTitle = lead.vehicles ? (lead.vehicles as any).title : "vehicle";
    const oName = lead.organizations ? (lead.organizations as any).name : "Vendor";
    
    await sendLeadConvertedEmail({
      to: lead.customer_email,
      customerName: lead.customer_name || "there",
      vehicleTitle: vTitle,
      vendorName: oName,
      leadId: lead.id,
    }).catch(e => console.error("Failed to send conversion email", e));
  }

  // Add lead event
  await supabase.from("lead_events").insert({
    lead_id: leadId,
    actor_user_id: user.id,
    event_type: `status_changed_${status}`,
    metadata: {
      previous_status: oldStatus,
      new_status: status,
      notes: notes || null,
    },
  });

  // Add moderation note if provided
  if (notes) {
    await supabase.from("moderation_notes").insert({
      resource_type: "lead",
      resource_id: leadId,
      author_user_id: user.id,
      body: notes,
    });
  }

  // Log audit event
  await supabase.from("audit_logs").insert({
    actor_user_id: user.id,
    action: "lead_status_updated",
    resource_type: "lead",
    resource_id: leadId,
    metadata: {
      organization_id: organizationId,
      previous_status: oldStatus,
      new_status: status,
    },
  });

  revalidatePath("/vendor/leads");
  revalidatePath("/vendor/dashboard");
}

export async function addLeadNote(formData: FormData): Promise<void> {
  const user = await requireUser();

  const leadId = formData.get("leadId") as string;
  const organizationId = formData.get("organizationId") as string;
  const note = formData.get("note") as string;

  if (!leadId || !organizationId || !note || note.length > 1000) {
    throw new Error("Invalid input");
  }

  // Verify user has permission
  await ensureUserCanManageOrganization(user.id, organizationId);

  const supabase = createAdminClient();

  // Verify lead belongs to organization
  const { data: lead } = await supabase
    .from("leads")
    .select("id")
    .eq("id", leadId)
    .eq("vendor_id", organizationId)
    .single();

  if (!lead) {
    throw new Error("Lead not found or access denied");
  }

  // Add lead event for note
  await supabase.from("lead_events").insert({
    lead_id: leadId,
    actor_user_id: user.id,
    event_type: "note_added",
    metadata: { note },
  });

  revalidatePath("/vendor/leads");
}

"use server";

// redirect removed
import { revalidatePath } from "next/cache";
import { createAdminClient } from "@/lib/supabase/admin";
import { requireUser } from "@/lib/security/auth";
import { ensureUserCanManageOrganization } from "@/lib/data/vendor";
import { z } from "zod";

const profileSchema = z.object({
  organizationId: z.string().uuid(),
  name: z.string().trim().min(2).max(160),
  phone: z.string().trim().min(8).max(30).optional().or(z.literal("")),
  website: z.string().url().optional().or(z.literal("")),
  address: z.string().trim().min(6).max(240).optional().or(z.literal("")),
});

export async function updateOrganizationProfile(prevState: any, formData: FormData) {
  const user = await requireUser();

  const parsed = profileSchema.safeParse({
    organizationId: formData.get("organizationId"),
    name: formData.get("name"),
    phone: formData.get("phone") || "",
    website: formData.get("website") || "",
    address: formData.get("address") || "",
  });

  if (!parsed.success) {
    return { error: "Invalid form data. Please check your inputs.", success: false };
  }

  const { organizationId, name, phone, website, address } = parsed.data;

  await ensureUserCanManageOrganization(user.id, organizationId);

  const supabase = createAdminClient();
  const { error } = await supabase
    .from("organizations")
    .update({
      name,
      phone: phone || null,
      website: website || null,
      address: address || null,
      updated_at: new Date().toISOString(),
    })
    .eq("id", organizationId);

  if (error) {
    return { error: `Failed to update organization: ${error.message}`, success: false };
  }

  await supabase.from("audit_logs").insert({
    actor_user_id: user.id,
    action: "organization_profile_updated",
    resource_type: "organization",
    resource_id: organizationId,
    metadata: { fields: ["name", "phone", "website", "address"] },
  });

  revalidatePath("/vendor/settings");
  return { success: true, error: null };
}

export async function updateBrandProfile(prevState: any, formData: FormData) {
  const user = await requireUser();
  const organizationId = formData.get("organizationId") as string;
  const bio = formData.get("bio") as string;
  const logo = formData.get("logo") as File | null;

  if (!organizationId) return { error: "Missing organization ID" };

  await ensureUserCanManageOrganization(user.id, organizationId);
  const supabase = createAdminClient();

  let logoUrl: string | undefined = undefined;

  if (logo && logo.size > 0) {
    if (logo.size > 2 * 1024 * 1024) {
      return { error: "Logo must be less than 2MB" };
    }

    const ext = logo.name.split(".").pop() ?? "png";
    const path = `logos/${organizationId}-${Date.now()}.${ext}`;

    // Upload to a generic public bucket (e.g. vendor-documents or vehicle-images)
    // we use vehicle-images since it's already configured as public in the DB
    const buffer = await logo.arrayBuffer();
    const { error: uploadError } = await supabase.storage
      .from("vehicle-images")
      .upload(path, buffer, { 
        upsert: true,
        contentType: logo.type,
      });

    if (uploadError) {
      return { error: `Failed to upload logo: ${uploadError.message}` };
    }

    const { data } = supabase.storage.from("vehicle-images").getPublicUrl(path);
    logoUrl = data.publicUrl;
  }

  const updates: any = {};
  if (bio !== undefined) updates.bio = bio;
  if (logoUrl !== undefined) updates.logo_url = logoUrl;

  if (Object.keys(updates).length > 0) {
    const { error } = await supabase
      .from("organizations")
      .update(updates)
      .eq("id", organizationId);

    if (error) {
      return { error: error.message };
    }
  }

  revalidatePath("/vendor/settings");
  return { success: true, error: null };
}

export async function uploadVendorDocument(formData: FormData) {
  const user = await requireUser();
  const organizationId = String(formData.get("organizationId") ?? "");
  const documentType = String(formData.get("documentType") ?? "abn_certificate");
  const file = formData.get("file") as File | null;

  if (!organizationId || !file?.size) {
    throw new Error("Organization and file are required.");
  }

  await ensureUserCanManageOrganization(user.id, organizationId);

  const supabase = createAdminClient();
  const ext = file.name.split(".").pop() ?? "pdf";
  const path = `${organizationId}/${documentType}-${Date.now()}.${ext}`;

  const { error: uploadError } = await supabase.storage
    .from("vendor-documents")
    .upload(path, file, { upsert: false });

  if (uploadError) {
    throw new Error(uploadError.message);
  }

  const { error: dbError } = await supabase.from("vendor_documents").insert({
    organization_id: organizationId,
    document_type: documentType,
    storage_path: path,
    status: "pending",
  });

  if (dbError) {
    throw new Error(dbError.message);
  }

  revalidatePath("/vendor/settings");
}

"use client";

import { useActionState, useRef, useState } from "react";
import { updateBrandProfile } from "./actions";
import { ImageIcon } from "lucide-react";

export function BrandForm({ organizationId, defaultBio, defaultLogoUrl }: { organizationId: string, defaultBio?: string | null, defaultLogoUrl?: string | null }) {
  const [state, formAction, isPending] = useActionState<any, FormData>(updateBrandProfile, { error: null });
  const [logoPreview, setLogoPreview] = useState<string | null>(defaultLogoUrl || null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setLogoPreview(url);
    }
  };

  return (
    <form action={formAction} className="space-y-5" encType="multipart/form-data">
      <input type="hidden" name="organizationId" value={organizationId} />
      
      {state.error && (
        <div className="rounded-lg bg-red-50 p-3 text-sm text-red-600">
          {state.error}
        </div>
      )}
      {state.success && (
        <div className="rounded-lg bg-emerald-50 p-3 text-sm text-emerald-600">
          Brand profile updated successfully.
        </div>
      )}

      <div>
        <label htmlFor="logo" className="block text-sm font-medium text-foreground mb-1.5">Brand Logo</label>
