          className="w-full rounded-xl border border-input bg-background px-4 py-2.5 text-sm text-foreground placeholder:text-muted-foreground focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/50 transition-all resize-none"
          placeholder="Tell customers about your fleet, service quality, and history..."
          aria-describedby="bio-helper"
        />
        <p id="bio-helper" className="mt-1.5 text-xs text-muted-foreground">Displayed on your public vendor profile page</p>
      </div>
      
      <button disabled={isPending} type="submit" className="w-full rounded-xl bg-card border border-border px-4 py-2.5 text-sm font-semibold text-foreground hover:bg-muted transition-colors shadow-sm disabled:opacity-50">
        {isPending ? "Saving..." : "Save Profile Settings"}
      </button>
    </form>
  );
}

"use server";

import { revalidatePath } from "next/cache";
import { createAdminClient } from "@/lib/supabase/admin";
import { requireUser } from "@/lib/security/auth";
import { ensureUserCanManageOrganization, getVehicleLimitInfo } from "@/lib/data/vendor";
import { requirePlanFeature } from "@/lib/plan-features";
import { invalidatePseoForVehicle } from "@/lib/seo/vehicle-invalidation";
import * as xlsx from "xlsx";
import { uniqueSlug } from "@/lib/slug";

const MAX_UPLOAD_SIZE_BYTES = 8 * 1024 * 1024;
const SUPPORTED_EXTENSIONS = new Set(["csv", "xlsx", "xls"]);

export async function processBulkUpload(formData: FormData) {
  try {
    const user = await requireUser();
    const organizationId = formData.get("organizationId") as string;
    const branchId = formData.get("branchId") as string;
    const fileValue = formData.get("file");

    if (!organizationId || !branchId || !(fileValue instanceof File)) {
      return { success: false, error: "Missing required fields" };
    }

    const file = fileValue;
    const extension = file.name.split(".").pop()?.toLowerCase();

    if (!extension || !SUPPORTED_EXTENSIONS.has(extension)) {
      return { success: false, error: "Unsupported file type. Upload a CSV, XLSX, or XLS file." };
    }

    if (file.size > MAX_UPLOAD_SIZE_BYTES) {
      return { success: false, error: "The uploaded file is too large. Please upload a file smaller than 8 MB." };
    }

    await ensureUserCanManageOrganization(user.id, organizationId);
    await requirePlanFeature(organizationId, "bulkUpload");

    const supabase = createAdminClient();

    // Verify branch belongs to organization
    const { data: branch } = await supabase
      .from("branches")
      .select("id")
      .eq("id", branchId)
      .eq("organization_id", organizationId)
      .single();

    if (!branch) {
      return { success: false, error: "Invalid branch" };
    }

    // Read the file using xlsx
    const buffer = await file.arrayBuffer();
    const workbook = xlsx.read(buffer, { type: "array", cellDates: false });
    const firstSheetName = workbook.SheetNames[0];

    if (!firstSheetName) {
      return { success: false, error: "The uploaded file does not contain any sheets." };
    }

    const worksheet = workbook.Sheets[firstSheetName];
    
    // Convert to JSON
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const rows = xlsx.utils.sheet_to_json(worksheet) as any[];

    if (rows.length === 0) {
      return { success: false, error: "The uploaded file is empty." };
    }

    const limitInfo = await getVehicleLimitInfo(organizationId);
    if (limitInfo.hasLimit && limitInfo.limit !== null) {
      if (limitInfo.currentCount + rows.length > limitInfo.limit) {
        return { success: false, error: `Upload rejected. Your current plan limit is ${limitInfo.limit} vehicles. You already have ${limitInfo.currentCount}, and this file contains ${rows.length} vehicles. Please upgrade your plan or upload fewer vehicles.` };
      }
    }

    const errors: string[] = [];
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const inserts: any[] = [];

    // Process each row
    rows.forEach((row, index) => {
      // Map common column names to our schema
      const make = String(row["Make"] || row["make"] || "");
      const model = String(row["Model"] || row["model"] || "");
      const year = parseInt(row["Year"] || row["year"]);
      const vin = String(row["Vin"] || row["VIN"] || row["vin"] || "");
      const licensePlate = String(row["License Plate"] || row["License_Plate"] || row["license_plate"] || "");
      const category = String(row["Category"] || row["category"] || "Sedan");
      const color = String(row["Color"] || row["color"] || "");
      const fuel = String(row["Fuel Type"] || row["Fuel_Type"] || row["fuel"] || "Petrol");
      const transmission = String(row["Transmission"] || row["transmission"] || "Automatic");
      const seats = parseInt(row["Seats"] || row["seats"] || "5");
      const dailyRate = parseInt(row["Daily Rate"] || row["daily_rate"] || row["price_per_day_aud"] || "0");
      const hourlyRate = parseInt(row["Hourly Rate"] || row["hourly_rate"] || "0");
      const weeklyRate = parseInt(row["Weekly Rate"] || row["weekly_rate"] || "0");
      const monthlyRate = parseInt(row["Monthly Rate"] || row["monthly_rate"] || "0");
      const weekendRate = parseInt(row["Weekend Rate"] || row["weekend_rate"] || "0");
      const extraMileageCharge = parseFloat(row["Extra Mileage Charge"] || row["extra_distance_fee_aud"] || "0");
      const milesPerDay = parseInt(row["Miles Per Day"] || row["daily_distance_limit_km"] || "0");
      const notes = String(row["Notes"] || row["notes"] || "");

      // Validate required fields
      if (!make || !model || isNaN(year) || isNaN(dailyRate) || dailyRate < 20) {
        errors.push(`Row ${index + 2}: Missing or invalid required fields (Make, Model, Year, Daily Rate).`);
        return;
      }

      inserts.push({
        organization_id: organizationId,
        branch_id: branchId,
        slug: uniqueSlug(`${make} ${model} ${year}`),
        title: `${year} ${make} ${model}`,
        make,
        model,
        year,
        seats: isNaN(seats) ? 5 : seats,
        fuel: fuel.charAt(0).toUpperCase() + fuel.slice(1).toLowerCase(), // e.g. "Diesel"
        transmission: transmission.charAt(0).toUpperCase() + transmission.slice(1).toLowerCase(),
        category,
        price_per_day_aud: dailyRate,
        daily_distance_limit_km: isNaN(milesPerDay) || milesPerDay === 0 ? null : milesPerDay,
        extra_distance_fee_aud: isNaN(extraMileageCharge) || extraMileageCharge === 0 ? null : extraMileageCharge,
        instant_book: false,
        status: "approved", // Bulk uploaded by vendor, we can set it to approved directly for enterprise users
        vin: vin || null,
        license_plate: licensePlate || null,
        color: color || null,
        hourly_rate_aud: isNaN(hourlyRate) || hourlyRate === 0 ? null : hourlyRate,
        weekly_rate_aud: isNaN(weeklyRate) || weeklyRate === 0 ? null : weeklyRate,
        monthly_rate_aud: isNaN(monthlyRate) || monthlyRate === 0 ? null : monthlyRate,
        weekend_rate_aud: isNaN(weekendRate) || weekendRate === 0 ? null : weekendRate,
        notes: notes || null,
      });
    });

    if (errors.length > 0 && inserts.length === 0) {
      return { success: false, errors };
    }

    if (inserts.length > 0) {
      const CHUNK_SIZE = 200;
      const allData: any[] = [];
      
      for (let i = 0; i < inserts.length; i += CHUNK_SIZE) {
        const chunk = inserts.slice(i, i + CHUNK_SIZE);
        const { data, error } = await supabase.from("vehicles").insert(chunk).select("id");
        
        if (error) {
          return { success: false, error: `Database error during bulk insert (batch ${Math.floor(i / CHUNK_SIZE) + 1}): ` + error.message };
        }
        
        if (data) {
          allData.push(...data);
        }
      }
      
      const data = allData;

      // Create search index jobs for the inserted vehicles
      if (data && data.length > 0) {
        const jobs = data.map((v) => ({
          vehicle_id: v.id,
          operation: "upsert",
          status: "pending",
        }));
        
        // Batch insert jobs as well
        for (let i = 0; i < jobs.length; i += CHUNK_SIZE) {
          await supabase.from("search_index_jobs").insert(jobs.slice(i, i + CHUNK_SIZE));
        }

        // Run PSEO invalidation synchronously but individually to prevent enormous payloads
        for (const v of data) {
          await invalidatePseoForVehicle(supabase, v.id);
        }

        // Audit Log
        await supabase.from("audit_logs").insert({
          actor_user_id: user.id,
          action: "bulk_vehicles_created",
          resource_type: "organization",
          resource_id: organizationId,
          metadata: { count: data.length, branch_id: branchId },
        });
      }
    }

    revalidatePath("/vendor/vehicles");
    revalidatePath("/vendor/dashboard");

    return { 
      success: true, 
      count: inserts.length,
      errors: errors.length > 0 ? errors : undefined 
    };

  } catch (error) {
    console.error("Bulk upload error:", error);
    return { success: false, error: "An unexpected error occurred processing the file." };
  }
}

"use client";

import { Trash2, Loader2 } from "lucide-react";
import { useState } from "react";
import { deleteVehicle } from "./actions";
import { toast } from "sonner";
import { useRouter } from "next/navigation";

interface DeleteVehicleButtonProps {
  vehicleId: string;
  organizationId: string;
}

export function DeleteVehicleButton({ vehicleId, organizationId }: DeleteVehicleButtonProps) {
  const [isDeleting, setIsDeleting] = useState(false);
  const router = useRouter();

  const handleDelete = async () => {
    if (!confirm("Are you sure you want to delete this vehicle? This action cannot be undone.")) return;

    setIsDeleting(true);
    const formData = new FormData();
    formData.append("vehicleId", vehicleId);
    formData.append("organizationId", organizationId);

    try {
      const result = await deleteVehicle(formData);
      if (result.success) {
        toast.success("Vehicle deleted successfully");
        router.refresh(); // Force a hard refresh of the current route to update the UI
      } else {
        toast.error(result.error || "Failed to delete vehicle");
      }
    } catch (err) {
      toast.error("An unexpected error occurred");
    } finally {
      setIsDeleting(false);
    }
  };

  return (
    <button
      type="button"
      onClick={handleDelete}
      disabled={isDeleting}
      className="flex items-center justify-center h-9 w-9 rounded-lg border border-red-200 bg-white text-red-600 hover:border-red-300 hover:bg-red-50 hover:text-red-700 shadow-sm transition-all disabled:opacity-50 disabled:cursor-not-allowed"
      title="Delete"
    >
      {isDeleting ? <Loader2 className="h-4 w-4 animate-spin" /> : <Trash2 className="h-4 w-4" />}
    </button>
  );
}

import Link from "next/link";
import { redirect } from "next/navigation";
import { requireUser } from "@/lib/security/auth";
import { getVendorContext, getVehicleLimitInfo } from "@/lib/data/vendor";
import { getOrganizationVehicles, deleteVehicle, getVehicleFeatures } from "./actions";
import { getVehicleImages } from "./image-actions";
import VehicleForm from "./vehicle-form";
import { DeleteVehicleButton } from "./delete-button";
import { BulkUpload } from "@/components/vendor/bulk-upload";
import { OrgSwitcher } from "@/components/vendor/org-switcher";
import { organizationHasFeature } from "@/lib/plan-features";
import { Car, MapPin, Tag, Fuel, Settings2, Users, AlertCircle, Edit2, Eye } from "lucide-react";

export const metadata = {
  title: "Vehicles",
};

interface VehiclesPageProps {
  searchParams: Promise<{ org?: string; edit?: string; page?: string }>;
}

export default async function VendorVehiclesPage({ searchParams }: VehiclesPageProps) {
  const user = await requireUser();
  const params = await searchParams;
  const context = await getVendorContext(user.id);

  if (context.setupError) {
    return (
      <div className="rounded-2xl border border-red-200 bg-red-50 p-6">
        <h1 className="text-lg font-semibold text-red-800">Setup Required</h1>
        <p className="mt-2 text-red-700">{context.setupError}</p>
      </div>
    );
  }

  if (context.organizations.length === 0) {
    redirect("/vendor/upgrade");
  }

  const selectedOrgId = params.org || context.organizations[0]?.id;
  const organization = context.organizations.find((o) => o.id === selectedOrgId);

  if (!organization) {
    redirect("/vendor/vehicles?org=" + context.organizations[0]?.id);
  }

  const page = parseInt(params.page || "1", 10) || 1;
  const limitInfo = await getVehicleLimitInfo(selectedOrgId);
  const hasBulkUpload = await organizationHasFeature(selectedOrgId, "bulkUpload");
  const canUseAi = await organizationHasFeature(selectedOrgId, "aiSeoContent");
  const { vehicles, totalCount, pageSize } = await getOrganizationVehicles(selectedOrgId, page);

  let editVehicle: ((typeof vehicles)[number] & { features?: string[] }) | null = null;
  let editImages: Awaited<ReturnType<typeof getVehicleImages>> = [];
  if (params.edit) {
    const found = vehicles.find((v) => v.id === params.edit) ?? null;
    if (found) {
      const features = await getVehicleFeatures(params.edit, selectedOrgId);
      editVehicle = { ...found, features };
      editImages = await getVehicleImages(params.edit, selectedOrgId);
    }
  }

  const isAtLimit = limitInfo.hasLimit && limitInfo.currentCount >= (limitInfo.limit ?? 0);
  const usagePercent = limitInfo.limit ? Math.min((limitInfo.currentCount / limitInfo.limit) * 100, 100) : 0;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h1 className="text-2xl font-bold text-slate-900">Vehicles</h1>
            <p className="mt-1 text-sm text-slate-500">
              Manage your fleet listings for <span className="font-medium text-slate-700">{organization.name}</span>.
            </p>
          </div>
          <OrgSwitcher
            organizations={context.organizations}
            selectedOrgId={selectedOrgId}
            basePath="/vendor/vehicles"
          />
        </div>

        {/* Plan Usage */}
        <div className="mt-6 rounded-xl border border-slate-100 bg-slate-50 p-5">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm font-semibold text-slate-700">
              Plan Limit <span className="text-slate-400 font-normal">({limitInfo.planCode || "Free"})</span>
            </span>
            <span className="text-sm font-medium text-slate-700">
              {limitInfo.currentCount} <span className="text-slate-400 font-normal">/ {limitInfo.limit ?? "∞"} vehicles</span>
            </span>
          </div>
          {limitInfo.hasLimit && (
            <div className="h-2.5 rounded-full bg-slate-200 overflow-hidden">
              <div
                className={`h-2.5 rounded-full transition-all duration-700 ${isAtLimit ? "bg-red-500" : "bg-gradient-to-r from-blue-500 to-indigo-500"}`}
                style={{ width: `${usagePercent}%` }}
              />
            </div>
          )}
          {isAtLimit && (
            <div className="mt-3 flex items-start gap-2 text-sm text-red-600 bg-red-50 p-3 rounded-lg border border-red-100">
              <AlertCircle className="h-4.5 w-4.5 shrink-0" />
              <p>You have reached your vehicle limit. <Link href="/vendor/billing" className="font-semibold underline hover:text-red-700">Upgrade your plan</Link> to add more.</p>
            </div>
          )}
        </div>
      </div>

      {!editVehicle && hasBulkUpload && (
        <BulkUpload
          organizationId={selectedOrgId}
          branches={organization.branches}
        />
      )}
      {!editVehicle && !hasBulkUpload && (
        <div className="rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-600">
          Bulk upload is available on the <Link href="/vendor/billing" className="font-semibold text-orange-600 hover:underline">Pro plan</Link>.
        </div>
      )}

      {/* Vehicle Form */}
      <VehicleForm
        organizationId={selectedOrgId}
        branches={organization.branches}
        isAtLimit={isAtLimit}
        canUseAi={canUseAi}
        editVehicle={editVehicle}
        editImages={editImages}
      />

      {/* Vehicles List */}
      <div className="rounded-2xl border border-slate-200 bg-white shadow-sm overflow-hidden">
        <div className="border-b border-slate-100 px-6 py-5 bg-slate-50/50">
          <h2 className="text-base font-semibold text-slate-900">Your Fleet ({totalCount})</h2>
        </div>

        {vehicles.length === 0 ? (
          <div className="px-6 py-12 text-center">
            <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-slate-100 mb-4">
              <Car className="h-7 w-7 text-slate-400" />
            </div>
            <p className="text-base font-medium text-slate-900">No vehicles yet</p>
            <p className="text-sm text-slate-500 mt-1">Add your first vehicle using the form above.</p>
          </div>
        ) : (
          <div className="divide-y divide-slate-100">
            {vehicles.map((vehicle) => {
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              const branch = (vehicle as any).branches;
              return (
                <div key={vehicle.id} className="p-6 flex flex-col gap-5 sm:flex-row sm:items-start sm:justify-between hover:bg-slate-50 transition-colors group">
                  <div className="flex-1 space-y-3">
                    <div className="flex items-center gap-3">
                      <h3 className="text-lg font-bold text-slate-900 leading-none">{vehicle.title}</h3>
                      <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-semibold uppercase tracking-wider ${
                        vehicle.status === "approved" ? "bg-emerald-100 text-emerald-700" :
                        vehicle.status === "pending" ? "bg-amber-100 text-amber-700" :
                        "bg-red-100 text-red-700"
                      }`}>
                        {vehicle.status}
                      </span>
                    </div>

                    <div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-sm text-slate-600">
                      <span className="flex items-center gap-1.5 font-medium text-slate-900">
                        <Tag className="h-4 w-4 text-slate-400" />
                        ${vehicle.price_per_day_aud}/day
                      </span>
                      <span className="flex items-center gap-1.5">
                        <MapPin className="h-4 w-4 text-slate-400" />
                        {branch?.name} ({branch?.city})
                      </span>
                    </div>

                    <div className="flex flex-wrap gap-2 text-xs text-slate-500">
                      <span className="inline-flex items-center gap-1 bg-slate-100 px-2 py-1 rounded-md">
                        <Car className="h-3.5 w-3.5" /> {vehicle.category}
                      </span>
                      <span className="inline-flex items-center gap-1 bg-slate-100 px-2 py-1 rounded-md">
                        <Users className="h-3.5 w-3.5" /> {vehicle.seats} seats
                      </span>
                      <span className="inline-flex items-center gap-1 bg-slate-100 px-2 py-1 rounded-md">
                        <Settings2 className="h-3.5 w-3.5" /> {vehicle.transmission}
                      </span>
                      <span className="inline-flex items-center gap-1 bg-slate-100 px-2 py-1 rounded-md">
                        <Fuel className="h-3.5 w-3.5" /> {vehicle.fuel}
                      </span>
                    </div>
                  </div>

                  <div className="flex gap-2 sm:opacity-0 group-hover:opacity-100 transition-opacity shrink-0">
                    <Link
                      href={`/cars/${vehicle.slug}`}
                      target="_blank"
                      className="flex items-center justify-center h-9 w-9 rounded-lg border border-slate-200 bg-white text-slate-600 hover:border-slate-300 hover:bg-slate-50 hover:text-brand-600 shadow-sm transition-all"
                      title="View Public Listing"
                    >
                      <Eye className="h-4 w-4" />
                    </Link>
                    <Link
                      href={`/vendor/vehicles?org=${selectedOrgId}&edit=${vehicle.id}`}
                      className="flex items-center justify-center h-9 w-9 rounded-lg border border-slate-200 bg-white text-slate-600 hover:border-slate-300 hover:bg-slate-50 hover:text-slate-900 shadow-sm transition-all"
                      title="Edit"
                    >
                      <Edit2 className="h-4 w-4" />
                    </Link>
                    <DeleteVehicleButton vehicleId={vehicle.id} organizationId={selectedOrgId} />
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {totalCount > pageSize && (
          <div className="border-t border-slate-100 px-6 py-4 flex items-center justify-between bg-slate-50/50">
            <p className="text-sm text-slate-500 font-medium">
              Showing {((page - 1) * pageSize) + 1} to {Math.min(page * pageSize, totalCount)} of {totalCount} vehicles
            </p>
            <div className="flex gap-2">
              {page > 1 && (
                <Link
                  href={`/vendor/vehicles?org=${selectedOrgId}&page=${page - 1}`}
                  className="rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-sm font-medium text-slate-700 hover:bg-slate-50 shadow-sm transition-colors"
                >
                  Previous
                </Link>
              )}
              {page * pageSize < totalCount && (
                <Link
                  href={`/vendor/vehicles?org=${selectedOrgId}&page=${page + 1}`}
                  className="rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-sm font-medium text-slate-700 hover:bg-slate-50 shadow-sm transition-colors"
                >
                  Next
                </Link>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

