"use client";

import Image from "next/image";
import { useState, useCallback, useRef } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { Sparkles, UploadCloud, X, AlertCircle, Loader2 } from "lucide-react";
import { createVehicle, updateVehicle } from "./actions";
import { getVehicleAutofill } from "./ai-actions";
import { uploadTempVehicleImage, deleteTempVehicleImage, deleteVehicleImage } from "./image-actions";
import { VEHICLE_FEATURES } from "@/lib/vehicle-badges";

interface VehicleFormProps {
  organizationId: string;
  branches: Array<{
    id: string;
    name: string;
    city: string;
  }>;
  isAtLimit: boolean;
  canUseAi?: boolean;
  editVehicle: {
    id: string;
    title: string;
    make: string;
    model: string;
    year: number;
    seats: number;
    fuel: string;
    transmission: string;
    category: string;
    price_per_day_aud: number;
    daily_distance_limit_km?: number | null;
    extra_distance_fee_aud?: number | null;
    instant_book?: boolean;
    vin?: string | null;
    license_plate?: string | null;
    color?: string | null;
    hourly_rate_aud?: number | null;
    weekly_rate_aud?: number | null;
    monthly_rate_aud?: number | null;
    weekend_rate_aud?: number | null;
    notes?: string | null;
    features?: string[];
    free_delivery?: boolean;
    free_cancellation?: boolean;
    no_hidden_fees?: boolean;
    branch_id: string;
    status: string;
  } | null;
  editImages: Array<{
    id: string;
    storage_path: string;
    alt_text: string;
    sort_order: number;
    approved: boolean;
    url: string | null;
  }>;
}

const categories = ["Sedan", "SUV", "People mover", "Van", "Ute", "Luxury"];
const fuelTypes = ["Petrol", "Diesel", "Hybrid", "Electric"];
const transmissions = ["Automatic", "Manual"];

type PendingImage = {
  id: string; // local id
  file: File;
  previewUrl: string;
  uploading: boolean;
  error?: string;
  serverPath?: string;
};

export default function VehicleForm({
  organizationId,
  branches,
  isAtLimit,
  canUseAi = false,
  editVehicle,
  editImages: initialEditImages,
}: VehicleFormProps) {
  const router = useRouter();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [message, setMessage] = useState<{ type: "success" | "error"; text: string } | null>(null);
  const [pendingUploads, setPendingUploads] = useState<PendingImage[]>([]);
  const [editImages, setEditImages] = useState(initialEditImages);
  
  const [notes, setNotes] = useState(editVehicle?.notes || "");
  const [aiLoading, setAiLoading] = useState(false);
  const [formState, setFormState] = useState({
    title: editVehicle?.title || "",
    seats: editVehicle?.seats || 5,
    fuel: editVehicle?.fuel || "Petrol",
    transmission: editVehicle?.transmission || "Automatic",
    category: editVehicle?.category || "Sedan",
  });

  const isUploading = pendingUploads.some(img => img.uploading);

  async function handleAiGenerate(form: HTMLFormElement) {
    if (!canUseAi) return;
    const make = String(new FormData(form).get("make") ?? "");
    const model = String(new FormData(form).get("model") ?? "");
    const year = Number(new FormData(form).get("year") ?? new Date().getFullYear());
    
    if (!make || !model || !year) {
      toast.error("Please fill out Make, Model, and Year first.");
      return;
    }

    setAiLoading(true);
    try {
      const result = await getVehicleAutofill({ organizationId, make, model, year });
      if (!result.ok) {
        toast.error(result.error);
        return;
      }
      setFormState({
        title: result.data.title,
        seats: result.data.seats,
        fuel: result.data.fuel,
        transmission: result.data.transmission,
        category: result.data.category,
      });
      setNotes(result.data.description);
      toast.success("Magic Autofill complete!");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "AI generation failed");
    } finally {
      setAiLoading(false);
    }
  }

  // Handle Drag and Drop
  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFilesSelected(Array.from(e.dataTransfer.files));
    }
  }, [pendingUploads.length, editImages.length]);

  const handleFilesSelected = async (files: File[]) => {
    if (isSubmitting) return;

    const currentTotal = editImages.length + pendingUploads.length;
    if (currentTotal + files.length > 10) {
      toast.error("Maximum 10 images per vehicle allowed.");
      files = files.slice(0, 10 - currentTotal);
    }

    if (files.length === 0) return;

    const newPending: PendingImage[] = files.map(f => ({
      id: Math.random().toString(36).substring(7),
      file: f,
      previewUrl: URL.createObjectURL(f),
      uploading: true,
    }));

    setPendingUploads(prev => [...prev, ...newPending]);

    // Instantly upload files
    for (const pending of newPending) {
      const imgData = new FormData();
      imgData.append("organizationId", organizationId);
      imgData.append("file", pending.file);

      try {
        const res = await uploadTempVehicleImage(imgData);
        setPendingUploads(prev => prev.map(p => {
          if (p.id === pending.id) {
            if (res.success) {
              return { ...p, uploading: false, serverPath: res.path, previewUrl: res.url || p.previewUrl };
            } else {
              toast.error(`Upload failed: ${res.error}`);
              return { ...p, uploading: false, error: res.error };
            }
          }
          return p;
        }));
      } catch (err) {
        toast.error("Network error during upload");
        setPendingUploads(prev => prev.map(p => p.id === pending.id ? { ...p, uploading: false, error: "Network error" } : p));
      }
    }
  };

  const removePendingImage = async (id: string) => {
    const img = pendingUploads.find(p => p.id === id);
    setPendingUploads(prev => prev.filter(p => p.id !== id));
    if (img?.previewUrl) URL.revokeObjectURL(img.previewUrl);
    
    // Cleanup on server if it was uploaded
    if (img?.serverPath && !img.uploading) {
      const fd = new FormData();
      fd.append("organizationId", organizationId);
      fd.append("path", img.serverPath);
      await deleteTempVehicleImage(fd).catch(console.error);
    }
  };

  const handleDeleteImage = async (imageId: string) => {
    if (!editVehicle || !confirm("Delete this image?")) return;

    const formData = new FormData();
    formData.append("imageId", imageId);
    formData.append("organizationId", organizationId);

    const result = await deleteVehicleImage(formData);

    if (result.success) {
      toast.success("Image deleted");
      setEditImages(prev => prev.filter(img => img.id !== imageId));
    } else {
      toast.error(result.error);
    }
  };

  async function handleSubmit(formData: FormData) {
    if (isUploading) {
      toast.error("Please wait for images to finish uploading before saving.");
      return;
    }

    setIsSubmitting(true);
    setMessage(null);

    formData.append("organizationId", organizationId);

    // Append successfully uploaded temp images
    const tempPaths = pendingUploads
      .filter(p => p.serverPath && !p.error)
      .map(p => p.serverPath);
    
    if (tempPaths.length > 0) {
      formData.append("tempImagePaths", JSON.stringify(tempPaths));
    }

    try {
      const result = editVehicle
        ? await updateVehicle(formData)
        : await createVehicle(formData);

      if (!result.success) {
        setMessage({ type: "error", text: result.error });
        setIsSubmitting(false);
        // Scroll to top to see error
        window.scrollTo({ top: 0, behavior: 'smooth' });
        return;
      }

      toast.success(editVehicle ? "Vehicle updated successfully!" : "Vehicle created successfully!");
      
      if (!editVehicle) {
        setPendingUploads([]);
        setNotes("");
        setFormState({ title: "", seats: 5, fuel: "Petrol", transmission: "Automatic", category: "Sedan" });
        const formEl = document.getElementById("vehicle-form") as HTMLFormElement;
        if (formEl) formEl.reset();
      }
      
      router.push(`/vendor/vehicles?org=${organizationId}`);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setMessage({ type: "error", text: `Error: ${msg}` });
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <form id="vehicle-form" action={handleSubmit} className="relative pb-24">
      {editVehicle && <input type="hidden" name="vehicleId" value={editVehicle.id} />}
      
      <div className="mb-6 flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-slate-900">
            {editVehicle ? "Edit Vehicle" : "Add New Vehicle"}
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            {editVehicle ? "Update your vehicle listing details below." : "Enter the details for your new vehicle listing."}
          </p>
        </div>
      </div>

      {message && (
        <div className={`mb-6 rounded-lg p-4 flex gap-3 items-start border shadow-sm ${
          message.type === "success" 
            ? "bg-emerald-50 text-emerald-900 border-emerald-200" 
            : "bg-red-50 text-red-900 border-red-200"
        }`}>
          {message.type === "error" && <AlertCircle className="w-5 h-5 text-red-600 mt-0.5 shrink-0" />}
          <div className="font-medium text-sm leading-relaxed">{message.text}</div>
        </div>
      )}

      {isAtLimit && !editVehicle && (
        <div className="mb-6 rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm font-medium text-amber-900 flex gap-3 items-start shadow-sm">
          <AlertCircle className="w-5 h-5 text-amber-600 shrink-0" />
          You have reached your vehicle limit. Upgrade your plan to add more vehicles.
        </div>
      )}

      <div className="space-y-8">
        
        {/* Section 1: Basic Information */}
        <section className="rounded-xl border border-slate-200 bg-white shadow-sm overflow-hidden">
          <div className="bg-slate-50/50 px-6 py-4 border-b border-slate-100 flex items-center justify-between">
            <h2 className="text-base font-semibold text-slate-900">Basic Information</h2>
            {canUseAi && (
              <button
                type="button"
                disabled={aiLoading}
                onClick={(e) => handleAiGenerate(document.getElementById("vehicle-form") as HTMLFormElement)}
                className="inline-flex items-center gap-1.5 text-xs font-semibold text-orange-600 hover:text-orange-700 bg-orange-50 hover:bg-orange-100 px-3 py-1.5 rounded-full transition-colors disabled:opacity-50 border border-orange-200"
              >
                <Sparkles className="h-3.5 w-3.5" />
                {aiLoading ? "Thinking..." : "Magic Autofill"}
              </button>
            )}
          </div>
          <div className="p-6 grid gap-6 md:grid-cols-2">
            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Listing Title
              <input name="title" value={formState.title} onChange={(e) => setFormState({ ...formState, title: e.target.value })} required maxLength={140} placeholder="e.g., 2023 Toyota Camry Hybrid" className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
            </label>
            
            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Branch Location
              <select name="branchId" defaultValue={editVehicle?.branch_id || ""} required className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal text-slate-900 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all">
                <option value="">Select a branch</option>
                {branches.map((b) => (
                  <option key={b.id} value={b.id}>{b.name} ({b.city})</option>
                ))}
              </select>
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Make
              <input name="make" defaultValue={editVehicle?.make || ""} required maxLength={80} placeholder="e.g., Toyota" className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Model
              <input name="model" defaultValue={editVehicle?.model || ""} required maxLength={80} placeholder="e.g., Camry" className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Year
              <input name="year" type="number" defaultValue={editVehicle?.year || new Date().getFullYear()} required min={1990} max={2030} className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal text-slate-900 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Category
              <select name="category" value={formState.category} onChange={(e) => setFormState({ ...formState, category: e.target.value })} required className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal text-slate-900 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all">
                {categories.map((c) => <option key={c} value={c}>{c}</option>)}
              </select>
            </label>
          </div>
        </section>

        {/* Section 2: Specifications */}
        <section className="rounded-xl border border-slate-200 bg-white shadow-sm overflow-hidden">
          <div className="bg-slate-50/50 px-6 py-4 border-b border-slate-100">
            <h2 className="text-base font-semibold text-slate-900">Specifications</h2>
          </div>
          <div className="p-6 grid gap-6 md:grid-cols-3">
            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Seats
              <input name="seats" type="number" value={formState.seats} onChange={(e) => setFormState({ ...formState, seats: Number(e.target.value) })} required min={2} max={12} className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal text-slate-900 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Fuel Type
              <select name="fuel" value={formState.fuel} onChange={(e) => setFormState({ ...formState, fuel: e.target.value })} required className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal text-slate-900 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all">
                {fuelTypes.map((t) => <option key={t} value={t}>{t}</option>)}
              </select>
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Transmission
              <select name="transmission" value={formState.transmission} onChange={(e) => setFormState({ ...formState, transmission: e.target.value })} required className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal text-slate-900 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all">
                {transmissions.map((t) => <option key={t} value={t}>{t}</option>)}
              </select>
            </label>
          </div>
        </section>

        {/* Section 3: Pricing & Terms */}
        <section className="rounded-xl border border-slate-200 bg-white shadow-sm overflow-hidden">
          <div className="bg-slate-50/50 px-6 py-4 border-b border-slate-100 flex items-center justify-between">
            <h2 className="text-base font-semibold text-slate-900">Pricing & Rules</h2>
            <label className="flex items-center gap-2 cursor-pointer group">
              <span className="text-sm font-semibold text-amber-700 group-hover:text-amber-800 transition-colors">Instant Book ⚡</span>
              <input type="checkbox" name="instantBook" defaultChecked={editVehicle?.instant_book || false} className="h-4 w-4 rounded border-amber-300 text-amber-600 focus:ring-amber-600 transition-all cursor-pointer" />
            </label>
          </div>
          <div className="p-6 grid gap-6 md:grid-cols-2 lg:grid-cols-4">
            <label className="grid gap-2 text-sm font-medium text-slate-900 lg:col-span-2">
              Daily Price (AUD)
              <div className="relative">
                <span className="absolute left-3 top-2.5 text-slate-400">$</span>
                <input name="pricePerDayAud" type="number" defaultValue={editVehicle?.price_per_day_aud || ""} required min={20} max={2000} className="w-full rounded-lg border-slate-200 bg-white pl-7 pr-3 py-2.5 font-normal text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" placeholder="75" />
              </div>
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Weekly Rate
              <div className="relative">
                <span className="absolute left-3 top-2.5 text-slate-400">$</span>
                <input name="weeklyRateAud" type="number" defaultValue={editVehicle?.weekly_rate_aud || ""} min={0} placeholder="Optional" className="w-full rounded-lg border-slate-200 bg-white pl-7 pr-3 py-2.5 font-normal text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
              </div>
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Monthly Rate
              <div className="relative">
                <span className="absolute left-3 top-2.5 text-slate-400">$</span>
                <input name="monthlyRateAud" type="number" defaultValue={editVehicle?.monthly_rate_aud || ""} min={0} placeholder="Optional" className="w-full rounded-lg border-slate-200 bg-white pl-7 pr-3 py-2.5 font-normal text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
              </div>
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Daily KM Limit
              <input name="dailyDistanceLimitKm" type="number" defaultValue={editVehicle?.daily_distance_limit_km || ""} min={50} max={1000} placeholder="Leave blank for unlimited" className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Extra KM Fee ($/km)
              <div className="relative">
                <span className="absolute left-3 top-2.5 text-slate-400">$</span>
                <input name="extraDistanceFeeAud" type="number" step="0.01" defaultValue={editVehicle?.extra_distance_fee_aud || ""} min={0.1} max={5.0} placeholder="0.35" className="w-full rounded-lg border-slate-200 bg-white pl-7 pr-3 py-2.5 font-normal text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
              </div>
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Weekend Rate
              <div className="relative">
                <span className="absolute left-3 top-2.5 text-slate-400">$</span>
                <input name="weekendRateAud" type="number" defaultValue={editVehicle?.weekend_rate_aud || ""} min={0} placeholder="Optional" className="w-full rounded-lg border-slate-200 bg-white pl-7 pr-3 py-2.5 font-normal text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
              </div>
            </label>
            
            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Hourly Rate
              <div className="relative">
                <span className="absolute left-3 top-2.5 text-slate-400">$</span>
                <input name="hourlyRateAud" type="number" defaultValue={editVehicle?.hourly_rate_aud || ""} min={0} placeholder="Optional" className="w-full rounded-lg border-slate-200 bg-white pl-7 pr-3 py-2.5 font-normal text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
              </div>
            </label>
          </div>
        </section>

        {/* Section 3b: Features & Inclusions */}
        <section className="rounded-xl border border-slate-200 bg-white shadow-sm overflow-hidden">
          <div className="bg-slate-50/50 px-6 py-4 border-b border-slate-100">
            <h2 className="text-base font-semibold text-slate-900">Features & Inclusions</h2>
            <p className="text-xs text-slate-500 mt-0.5">Shown on your listing card to help renters choose.</p>
          </div>
          <div className="p-6 space-y-6">
            <fieldset className="grid gap-3 grid-cols-2 sm:grid-cols-3 lg:grid-cols-4">
              {VEHICLE_FEATURES.map((feature) => (
                <label key={feature} className="flex items-center gap-2.5 text-sm font-medium text-slate-700 cursor-pointer">
                  <input
                    type="checkbox"
                    name="features"
                    value={feature}
                    defaultChecked={editVehicle?.features?.includes(feature) ?? false}
                    className="h-4 w-4 rounded border-slate-300 text-brand-600 focus:ring-brand-500 cursor-pointer"
                  />
                  {feature}
                </label>
              ))}
            </fieldset>

            <div className="grid gap-3 sm:grid-cols-3 border-t border-slate-100 pt-6">
              <label className="flex items-center gap-2.5 text-sm font-medium text-slate-700 cursor-pointer">
                <input type="checkbox" name="freeDelivery" defaultChecked={editVehicle?.free_delivery || false} className="h-4 w-4 rounded border-slate-300 text-brand-600 focus:ring-brand-500 cursor-pointer" />
                Free delivery available
              </label>
              <label className="flex items-center gap-2.5 text-sm font-medium text-slate-700 cursor-pointer">
                <input type="checkbox" name="freeCancellation" defaultChecked={editVehicle?.free_cancellation || false} className="h-4 w-4 rounded border-slate-300 text-brand-600 focus:ring-brand-500 cursor-pointer" />
                Free cancellation
              </label>
              <label className="flex items-center gap-2.5 text-sm font-medium text-slate-700 cursor-pointer">
                <input type="checkbox" name="noHiddenFees" defaultChecked={editVehicle?.no_hidden_fees || false} className="h-4 w-4 rounded border-slate-300 text-brand-600 focus:ring-brand-500 cursor-pointer" />
                No hidden fees
              </label>
            </div>
          </div>
        </section>

        {/* Section 4: Details & Notes */}
        <section className="rounded-xl border border-slate-200 bg-white shadow-sm overflow-hidden">
          <div className="bg-slate-50/50 px-6 py-4 border-b border-slate-100">
            <h2 className="text-base font-semibold text-slate-900">Listing Description & Internal Data</h2>
          </div>
          <div className="p-6 grid gap-6 md:grid-cols-2">
            <label className="grid gap-2 text-sm font-medium text-slate-900 md:col-span-2">
              Public Description / Notes
              <textarea name="notes" value={notes} onChange={(e) => setNotes(e.target.value)} maxLength={1000} rows={4} placeholder="Describe the vehicle's condition, features, or rental rules..." className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              VIN (Internal only)
              <input name="vin" defaultValue={editVehicle?.vin || ""} maxLength={100} placeholder="Vehicle Identification Number" className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal uppercase text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              License Plate (Internal only)
              <input name="licensePlate" defaultValue={editVehicle?.license_plate || ""} maxLength={40} placeholder="e.g., ABC-123" className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal uppercase text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
            </label>

            <label className="grid gap-2 text-sm font-medium text-slate-900">
              Color
              <input name="color" defaultValue={editVehicle?.color || ""} maxLength={60} placeholder="e.g., Pearl White" className="rounded-lg border-slate-200 bg-white px-3 py-2.5 font-normal text-slate-900 placeholder:text-slate-400 focus:border-brand-500 focus:ring-brand-500 shadow-sm transition-all" />
            </label>
          </div>
        </section>

        {/* Section 5: Image Dropzone */}
        <section className="rounded-xl border border-slate-200 bg-white shadow-sm overflow-hidden">
          <div className="bg-slate-50/50 px-6 py-4 border-b border-slate-100 flex justify-between items-center">
            <div>
              <h2 className="text-base font-semibold text-slate-900">Vehicle Images</h2>
              <p className="text-xs text-slate-500 mt-0.5">Drag & drop up to 10 images. They upload instantly.</p>
            </div>
            <span className="text-xs font-semibold bg-slate-200 text-slate-700 px-2 py-1 rounded-full">
              {editImages.length + pendingUploads.length} / 10
            </span>
          </div>
          
          <div className="p-6">
            <div 
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
              className={`border-2 border-dashed rounded-xl p-10 text-center transition-all cursor-pointer group ${
                isUploading 
                  ? "border-slate-300 bg-slate-50" 
                  : "border-slate-300 hover:border-brand-500 hover:bg-brand-50/30"
              }`}
            >
              <input
                ref={fileInputRef}
                type="file"
                accept="image/jpeg,image/png,image/webp"
                multiple
                className="hidden"
                disabled={isSubmitting || editImages.length + pendingUploads.length >= 10}
                onChange={(e) => {
                  if (e.target.files) handleFilesSelected(Array.from(e.target.files));
                  e.target.value = "";
                }}
              />
              <div className="w-12 h-12 bg-brand-100 text-brand-600 rounded-full flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                <UploadCloud className="w-6 h-6" />
              </div>
              <p className="text-sm font-semibold text-slate-900">Click to browse or drag images here</p>
              <p className="text-xs text-slate-500 mt-1">JPEG, PNG, WEBP up to 10MB</p>
            </div>

            {/* Image Grid Preview */}
            {(editImages.length > 0 || pendingUploads.length > 0) && (
              <div className="mt-6 grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                
                {/* Existing Images */}
                {editImages.map((img) => (
                  <div key={img.id} className="group relative aspect-square rounded-xl overflow-hidden border border-slate-200 shadow-sm bg-slate-100">
                    {img.url ? (
                      <Image src={img.url} alt={img.alt_text || "Vehicle image"} fill className="object-cover transition-transform group-hover:scale-105" />
                    ) : null}
                    
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center backdrop-blur-[2px]">
                      <button type="button" onClick={(e) => { e.stopPropagation(); handleDeleteImage(img.id); }} className="bg-red-500 hover:bg-red-600 text-white rounded-full p-2 transform scale-90 group-hover:scale-100 transition-all shadow-lg" title="Delete image">
                        <X className="w-4 h-4" />
                      </button>
                    </div>
                    {!img.approved && (
                      <span className="absolute bottom-2 left-2 right-2 text-center rounded bg-amber-500/90 backdrop-blur-sm px-2 py-1 text-[10px] font-bold text-white shadow-sm uppercase tracking-wider">
                        Pending Moderation
                      </span>
                    )}
                  </div>
                ))}

                {/* Newly Dropped & Uploading Images */}
                {pendingUploads.map((pending) => (
                  <div key={pending.id} className={`group relative aspect-square rounded-xl overflow-hidden border shadow-sm ${pending.error ? "border-red-300" : "border-slate-200"} bg-slate-50`}>
                    <Image src={pending.previewUrl} alt="Pending upload" fill className={`object-cover transition-all ${pending.uploading ? "opacity-40 scale-105 blur-sm" : ""}`} />
                    
                    {pending.uploading && (
                      <div className="absolute inset-0 flex flex-col items-center justify-center gap-2">
                        <Loader2 className="w-6 h-6 text-brand-600 animate-spin" />
                        <span className="text-[10px] font-bold text-slate-900 bg-white/80 px-2 py-0.5 rounded-full shadow-sm backdrop-blur-sm">UPLOADING...</span>
                      </div>
                    )}

                    {pending.error && (
                      <div className="absolute inset-0 flex flex-col items-center justify-center bg-red-50/90 backdrop-blur-[1px] p-2 text-center">
                        <AlertCircle className="w-5 h-5 text-red-500 mb-1" />
                        <span className="text-[10px] font-bold text-red-700 leading-tight">FAILED</span>
                      </div>
                    )}

                    {!pending.uploading && (
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center backdrop-blur-[2px]">
                        <button type="button" onClick={(e) => { e.stopPropagation(); removePendingImage(pending.id); }} className="bg-slate-800 hover:bg-slate-900 text-white rounded-full p-2 transform scale-90 group-hover:scale-100 transition-all shadow-lg" title="Remove image">
                          <X className="w-4 h-4" />
                        </button>
                      </div>
                    )}
                    
                    {!pending.uploading && !pending.error && (
                       <span className="absolute bottom-2 left-2 right-2 text-center rounded bg-emerald-500/90 backdrop-blur-sm px-2 py-1 text-[10px] font-bold text-white shadow-sm uppercase tracking-wider">
                         Ready to Save
                       </span>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </section>
      </div>

      {/* Action Bar */}
      <div className="sticky bottom-4 z-20 mt-8 rounded-xl border border-slate-200 bg-white/95 backdrop-blur-md shadow-lg p-4">
        <div className="flex items-center justify-between gap-4">
          <div className="text-sm font-medium text-slate-600 hidden sm:block">
            {isUploading ? "Uploading images..." : "Ready to save."}
          </div>
          <div className="flex gap-3 w-full sm:w-auto">
            {editVehicle && (
              <button
                type="button"
                onClick={() => router.push(`/vendor/vehicles?org=${organizationId}`)}
                className="flex-1 sm:flex-none rounded-lg border border-slate-300 bg-white px-6 py-2.5 text-sm font-semibold text-slate-700 hover:bg-slate-50 transition-colors"
              >
                Cancel
              </button>
            )}
            <button
              type="submit"
              disabled={isSubmitting || (isAtLimit && !editVehicle) || isUploading}
              className="flex-1 sm:flex-none rounded-lg bg-slate-900 px-8 py-2.5 text-sm font-semibold text-white hover:bg-slate-800 disabled:bg-slate-400 disabled:cursor-not-allowed transition-all shadow-sm flex items-center justify-center gap-2"
            >
              {(isSubmitting || isUploading) && <Loader2 className="w-4 h-4 animate-spin" />}
              {isSubmitting 
                ? "Saving..." 
                : isUploading 
                  ? "Uploading..." 
                  : editVehicle ? "Save Changes" : "Create Vehicle"}
            </button>
          </div>
        </div>
      </div>
    </form>
  );
}

"use client";

import { useTransition } from "react";
import { Button } from "@/components/ui/button";
import { Loader2 } from "lucide-react";
import { toast } from "sonner";
import { useRouter } from "next/navigation";

interface ActionButtonProps {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  action: () => Promise<any>;
  label: string;
  loadingLabel?: string;
  variant?: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link";
  size?: "default" | "sm" | "lg" | "icon";
  className?: string;
  icon?: React.ReactNode;
}

export function ActionButton({
  action,
  label,
  loadingLabel = "Processing...",
  variant = "default",
  size = "sm",
  className = "",
  icon,
}: ActionButtonProps) {
  const [isPending, startTransition] = useTransition();
  const router = useRouter();

  const handleClick = (e: React.MouseEvent) => {
    e.preventDefault();
    if (isPending) return;

    startTransition(async () => {
      try {
        const result = await action() as any;
        if (result && typeof result === "object" && "error" in result) {
          toast.error(result.error);
        } else {
          toast.success("Action completed successfully");
          router.refresh();
        }
      } catch (err: unknown) {
        const errorMsg = err instanceof Error ? err.message : "An unexpected error occurred";
        toast.error(errorMsg);
      }
    });
  };

  return (
    <Button
      variant={variant}
      size={size}
      className={className}
      onClick={handleClick}
      disabled={isPending}
    >
      {isPending ? (
        <>
          <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
          {loadingLabel}
        </>
      ) : (
        <>
          {icon && <span className="mr-1">{icon}</span>}
          {label}
        </>
      )}
    </Button>
  );
}

"use client";

import { useState } from "react";
import {
  User,
  Store,
  CheckCircle2,
  Globe,
  Mail,
  Phone,
} from "lucide-react";
import { createClient } from "@/lib/supabase/client";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { BrandLogo } from "@/components/brand-logo";
import {
  resolvePostAuthDestination,
  type AuthRole,
} from "@/lib/routing";
import { GoogleAuthButton } from "@/components/auth/GoogleAuthButton";
import { EmailAuthForm } from "@/components/auth/EmailAuthForm";

interface AuthPanelProps {
  /** Candidate redirect target from the `redirectedFrom` query param. */
  redirectedFrom?: string | null;
  /** Optional plan carried through to vendor upgrade destinations. */
  plan?: string | null;
  /** Whether the page was reached because admin MFA is required. */
  mfaRequired?: boolean;
}

type AuthMethod = "google" | "email";

const METHOD_TABS: ReadonlyArray<{
  id: AuthMethod;
  label: string;
  icon: typeof Globe;
}> = [
  { id: "google", label: "Google", icon: Globe },
  { id: "email", label: "Email", icon: Mail },
];

const ROLE_OPTIONS: ReadonlyArray<{
  id: AuthRole;
  title: string;
  description: string;
  icon: typeof User;
}> = [
  {
    id: "customer",
    title: "I am a Customer",
    description: "Discover, compare, and rent vehicles.",
    icon: User,
  },
  {
    id: "vendor",
    title: "I am a Vendor",
    description: "List my fleet and receive leads.",
    icon: Store,
  },
];

/**
 * Unified sign-in panel composing the Google, Email, and Phone authentication
 * methods behind tabbed navigation.
 *
 * AuthPanel owns the `customer`/`vendor` role selection that drives the
 * post-login destination and renders shared authentication errors. Each child
 * method receives the selected role, the resolved safe `nextRoute` (computed
 * with `resolvePostAuthDestination`), the optional `plan`, and an `onError`
 * callback used for shared error rendering. The method tabs are only revealed
 * once a role is selected, preserving the existing "choose how you'll use the
 * platform" gate from the previous Google-only flow.
 */
export function AuthPanel({
  redirectedFrom,
  plan,
  mfaRequired,
}: AuthPanelProps) {
  const [selectedRole, setSelectedRole] = useState<AuthRole | null>(null);
  const [activeMethod, setActiveMethod] = useState<AuthMethod>("google");
  const [error, setError] = useState<string | null>(null);

  const nextRoute = selectedRole
    ? resolvePostAuthDestination(selectedRole, redirectedFrom, plan)
    : null;

  function selectRole(role: AuthRole) {
    setSelectedRole(role);
    setError(null);
  }

  return (
    <Card variant="elevated" className="w-full max-w-[768px] py-8 sm:py-10">
      <CardHeader className="text-center space-y-4">
        <div className="flex justify-center">
          <BrandLogo
            priority
            className="h-[48px] w-[180px] sm:h-[56px] sm:w-[220px]"
          />
        </div>
        <div>
          <CardTitle
            className="text-2xl sm:text-3xl font-bold tracking-tight text-foreground"
            style={{ letterSpacing: "-0.03em" }}
          >
            Welcome to Hire Car
          </CardTitle>
          <p className="mt-2 text-muted-foreground">
            How would you like to use our platform today?
          </p>
        </div>
      </CardHeader>

      <CardContent className="space-y-6">
        {mfaRequired && (
          <div
            className="rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900"
            role="status"
          >
            <p className="font-medium">
              Admin access requires two-factor authentication.
            </p>
            <p className="mt-1">
              Sign in, enroll MFA in your account, then visit{" "}
              <a href="/auth/mfa" className="font-semibold underline">
                /auth/mfa
              </a>
              .
            </p>
          </div>
        )}

        {/* Shared authentication error */}
        {error && (
          <div
            className="rounded-lg border border-destructive/30 bg-destructive/5 px-4 py-3 text-sm text-destructive"
            role="alert"
          >
            <p className="font-medium">{error}</p>
            <p className="mt-1 text-destructive/80">
              {error.includes("credentials") || error.includes("password")
                ? "Please check your credentials and try again."
                : error.includes("network") || error.includes("fetch")
                ? "Check your internet connection and try again."
                : "Please try again or contact support if the issue persists."}
            </p>
          </div>
        )}

        {/* Role Selection Grid */}
        <div className="grid gap-4 sm:grid-cols-2">
          {ROLE_OPTIONS.map((option) => {
            const Icon = option.icon;
            const isSelected = selectedRole === option.id;
            return (
              <button
                key={option.id}
                type="button"
                onClick={() => selectRole(option.id)}
                aria-pressed={isSelected}
                className={`group relative flex flex-col items-center justify-center rounded-xl border-2 p-6 text-center transition-all duration-200 ${
                  isSelected
                    ? "border-primary bg-primary/5 shadow-md"
                    : "border-border bg-card hover:border-muted-foreground/30 hover:shadow-md"
                }`}
              >
                <div
                  className={`flex h-14 w-14 items-center justify-center rounded-full mb-3 transition-colors ${
                    isSelected
                      ? "bg-primary text-primary-foreground"
                      : "bg-muted text-muted-foreground group-hover:bg-muted/80"
                  }`}
                >
                  <Icon className="h-7 w-7" />
                </div>
                <h2 className="text-lg font-bold text-foreground mb-1">
                  {option.title}
                </h2>
                <p className="text-sm text-muted-foreground">
                  {option.description}
                </p>
                {isSelected && (
                  <div className="absolute top-3 right-3 text-primary">
                    <CheckCircle2 className="h-5 w-5" />
                  </div>
                )}
              </button>
            );
          })}
        </div>

        {/* Method tabs + active method — revealed once a role is selected */}
        {selectedRole && nextRoute ? (
          <div className="space-y-6">
            <div
              role="tablist"
              aria-label="Sign-in method"
              className="grid grid-cols-2 gap-1 rounded-xl border border-border bg-muted/40 p-1"
            >
              {METHOD_TABS.map((tab) => {
                const Icon = tab.icon;
                const isActive = activeMethod === tab.id;
                return (
                  <button
                    key={tab.id}
                    type="button"
                    role="tab"
                    id={`auth-tab-${tab.id}`}
                    aria-selected={isActive}
                    aria-controls={`auth-panel-${tab.id}`}
                    onClick={() => {
                      setActiveMethod(tab.id);
                      setError(null);
                    }}
                    className={`flex items-center justify-center gap-2 rounded-lg px-3 py-2 text-sm font-medium transition-all ${
                      isActive
                        ? "bg-card text-foreground shadow-sm"
                        : "text-muted-foreground hover:text-foreground"
                    }`}
                  >
                    <Icon className="h-4 w-4" />
                    {tab.label}
                  </button>
                );
              })}
            </div>

            <div
              role="tabpanel"
              id={`auth-panel-${activeMethod}`}
              aria-labelledby={`auth-tab-${activeMethod}`}
            >
              {activeMethod === "google" && (
                <div className="flex flex-col items-center gap-4">
                  <GoogleAuthButton
                    role={selectedRole}
                    nextRoute={nextRoute}
                    plan={plan}
                    onError={setError}
                  />
                </div>
              )}

              {activeMethod === "email" && (
                <EmailAuthForm
                  role={selectedRole}
                  nextRoute={nextRoute}
                  plan={plan}
                  onError={setError}
                />
              )}
            </div>
          </div>
        ) : (
          <p className="text-center text-sm text-muted-foreground">
            Select how you want to use Hire Car to continue.
          </p>
        )}

        {/* Dev sign-in buttons (development only) */}
        {process.env.NODE_ENV === "development" && (
          <div className="mt-2 flex gap-6 justify-center border-t border-border pt-4">
            <button
              onClick={async () => {
                setSelectedRole("customer");
                setError(null);
                const supabase = createClient();
                sessionStorage.setItem("auth_intended_role", "customer");
                const { error: devError } = await supabase.auth.signInWithPassword({
                  email: "customer@example.com",
                  password: "password123",
                });
                if (devError) {
                  setError(devError.message);
                } else {
                  window.location.href = resolvePostAuthDestination(
                    "customer",
                    redirectedFrom,
                    plan,
                  );
                }
              }}
              className="text-sm font-medium text-muted-foreground hover:text-foreground underline transition-colors"
            >
              Dev: Customer
            </button>
            <button
              onClick={async () => {
                setSelectedRole("vendor");
                setError(null);
                const supabase = createClient();
                sessionStorage.setItem("auth_intended_role", "vendor");
                const { error: devError } = await supabase.auth.signInWithPassword({
                  email: "vendor@example.com",
                  password: "password123",
                });
                if (devError) {
                  setError(devError.message);
                } else {
                  window.location.href = resolvePostAuthDestination(
                    "vendor",
                    redirectedFrom,
                    plan,
                  );
                }
              }}
              className="text-sm font-medium text-muted-foreground hover:text-foreground underline transition-colors"
            >
              Dev: Vendor
            </button>
            <button
              onClick={async () => {
                setError(null);
                const supabase = createClient();
                const { error: devError } = await supabase.auth.signInWithPassword({
                  email: "admin@example.com",
                  password: "password123",
                });
                if (devError) {
                  setError(devError.message);
                } else {
                  window.location.href = redirectedFrom || "/admin";
                }
              }}
              className="text-sm font-medium text-muted-foreground hover:text-foreground underline transition-colors"
            >
              Dev: Admin
            </button>
          </div>
        )}

        <p className="text-center text-xs text-muted-foreground">
          By continuing, you agree to our Terms of Service and Privacy Policy.
        </p>
      </CardContent>
    </Card>
  );
}

export default AuthPanel;

"use client";

import { useState } from "react";
import { ArrowRight, Loader2, Mail, KeyRound, Lock, Key } from "lucide-react";
import { createClient } from "@/lib/supabase/client";
import { validateEmail } from "@/lib/auth/validation";
import { toFriendlyAuthError } from "@/lib/auth/errors";
import { useAuthRedirect } from "@/components/auth/useAuthRedirect";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

interface EmailAuthFormProps {
  /** The user-selected role that drives the post-login destination. */
  role: "customer" | "vendor";
  /** The resolved safe next route (e.g. from resolveNextRoute(role)). */
  nextRoute: string;
  /** Optional plan carried through to the email-confirmation callback link. */
  plan?: string | null;
  /** Surfaces auth errors to a parent (e.g. AuthPanel) for shared rendering. */
  onError?: (message: string | null) => void;
  /** Allows a parent to disable the form (e.g. while another method is busy). */
  disabled?: boolean;
}

/** Per-field validation messages shown inline beneath each input. */
interface FieldErrors {
  email?: string;
  password?: string;
  confirmPassword?: string;
  otp?: string;
}

type AuthMode = "sign-in" | "sign-up" | "otp";

export function EmailAuthForm({
  role,
  nextRoute,
  plan,
  onError,
  disabled,
}: EmailAuthFormProps) {
  const { redirectToDestination } = useAuthRedirect();

  const [mode, setMode] = useState<AuthMode>("sign-in");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [otp, setOtp] = useState("");
  
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [otpSent, setOtpSent] = useState(false);
  const [signupSuccess, setSignupSuccess] = useState(false);
  const [forgotPasswordSent, setForgotPasswordSent] = useState(false);

  function validateEmailInput(): boolean {
    const errors: FieldErrors = {};
    const emailResult = validateEmail(email);
    if (!emailResult.ok) errors.email = emailResult.message;
    setFieldErrors((prev) => ({ ...prev, email: errors.email }));
    return !errors.email;
  }

  function validatePasswordInput(): boolean {
    const errors: FieldErrors = {};
    if (!password || password.length < 8) {
      errors.password = "Password must be at least 8 characters.";
    }
    if (mode === "sign-up" && password !== confirmPassword) {
      errors.confirmPassword = "Passwords do not match.";
    }
    setFieldErrors((prev) => ({ ...prev, password: errors.password, confirmPassword: errors.confirmPassword }));
    return !errors.password && !errors.confirmPassword;
  }

  function validateOtpInput(): boolean {
    const errors: FieldErrors = {};
    if (!otp || otp.length !== 6) errors.otp = "Please enter the 6-digit code.";
    setFieldErrors((prev) => ({ ...prev, otp: errors.otp }));
    return !errors.otp;
  }

  async function handleForgotPassword() {
    onError?.(null);
    if (!validateEmailInput()) return;
    setIsSubmitting(true);
    const supabase = createClient();
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(email.trim(), {
        redirectTo: `${window.location.origin}/auth/callback?next=/account/reset-password`,
      });
      if (error) {
        onError?.(toFriendlyAuthError(error));
      } else {
        setForgotPasswordSent(true);
      }
    } catch (err) {
      onError?.(toFriendlyAuthError(err));
    } finally {
      setIsSubmitting(false);
    }
  }

  async function handlePasswordAuth(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (disabled || isSubmitting) return;

    onError?.(null);
    if (!validateEmailInput() || !validatePasswordInput()) return;

    setIsSubmitting(true);
    const supabase = createClient();
    sessionStorage.setItem("auth_intended_role", role);

    try {
      if (mode === "sign-up") {
        const callbackParams = new URLSearchParams({ next: nextRoute, role });
        if (plan) callbackParams.set("plan", plan);

        const { error } = await supabase.auth.signUp({
          email: email.trim(),
          password,
          options: {
            emailRedirectTo: `${window.location.origin}/auth/callback?${callbackParams.toString()}`,
            data: {
              role: role
            }
          },
        });

        if (error) {
          onError?.(toFriendlyAuthError(error));
        } else {
          setSignupSuccess(true);
        }
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email: email.trim(),
          password,
        });

        if (error) {
          onError?.(toFriendlyAuthError(error));
        } else {
          await redirectToDestination(nextRoute);
        }
      }
    } catch (err) {
      onError?.(toFriendlyAuthError(err));
    } finally {
      setIsSubmitting(false);
    }
  }

  async function handleSendOtp(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (disabled || isSubmitting) return;

    onError?.(null);
    if (!validateEmailInput()) return;

    setIsSubmitting(true);
    const supabase = createClient();
    sessionStorage.setItem("auth_intended_role", role);

    try {
      const callbackParams = new URLSearchParams({ next: nextRoute, role });
      if (plan) callbackParams.set("plan", plan);

      const { error } = await supabase.auth.signInWithOtp({
        email: email.trim(),
        options: {
          shouldCreateUser: true,
          emailRedirectTo: `${window.location.origin}/auth/callback?${callbackParams.toString()}`,
          data: {
            role: role
          }
        },
      });

      if (error) {
        onError?.(toFriendlyAuthError(error));
      } else {
        setOtpSent(true);
      }
    } catch (err) {
      onError?.(toFriendlyAuthError(err));
    } finally {
      setIsSubmitting(false);
    }
  }

  async function handleVerifyOtp(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (disabled || isSubmitting) return;

    onError?.(null);
    if (!validateOtpInput()) return;

    setIsSubmitting(true);
    const supabase = createClient();

    try {
      const { data, error } = await supabase.auth.verifyOtp({
        email: email.trim(),
        token: otp.trim(),
        type: "email",
      });

      if (error || !data.session) {
        onError?.(toFriendlyAuthError(error));
        setIsSubmitting(false);
        return;
      }

      await redirectToDestination(nextRoute);
    } catch (err) {
      onError?.(toFriendlyAuthError(err));
      setIsSubmitting(false);
    }
  }

  // Render forgot-password success message
  if (forgotPasswordSent) {
    return (
      <div className="space-y-4 text-center">
        <div className="rounded-lg border border-primary/20 bg-primary/5 px-4 py-6">
          <Mail className="mx-auto h-8 w-8 text-primary mb-3" />
          <h3 className="font-semibold text-lg mb-2">Check your email</h3>
          <p className="text-sm text-muted-foreground mb-4">
            We've sent a password reset link to <span className="font-medium text-foreground">{email}</span>
          </p>
          <Button
            variant="outline"
            onClick={() => {
              setForgotPasswordSent(false);
              setMode("sign-in");
            }}
          >
            Back to Sign In
          </Button>
        </div>
      </div>
    );
  }

  // Render post-signup success message
  if (signupSuccess) {
    return (
      <div className="space-y-4 text-center">
        <div className="rounded-lg border border-primary/20 bg-primary/5 px-4 py-6">
          <Mail className="mx-auto h-8 w-8 text-primary mb-3" />
          <h3 className="font-semibold text-lg mb-2">Check your email</h3>
          <p className="text-sm text-muted-foreground mb-4">
            We've sent a verification link to <span className="font-medium text-foreground">{email}</span>
          </p>
          <Button 
            variant="outline" 
            onClick={() => {
              setSignupSuccess(false);
              setMode("sign-in");
            }}
          >
            Back to Sign In
          </Button>
        </div>
      </div>
    );
  }

  // Render OTP verification input
  if (mode === "otp" && otpSent) {
    return (
      <form onSubmit={handleVerifyOtp} className="space-y-4" noValidate>
        <div className="space-y-2">
          <Label htmlFor="email-auth-otp">Enter verification code</Label>
          <Input
            id="email-auth-otp"
            type="text"
            name="otp"
            autoComplete="one-time-code"
            inputMode="numeric"
            placeholder="123456"
            value={otp}
            maxLength={6}
            onChange={(event) => setOtp(event.target.value.replace(/\D/g, ""))}
            disabled={disabled || isSubmitting}
            aria-invalid={Boolean(fieldErrors.otp)}
          />
          {fieldErrors.otp ? (
            <p className="text-sm text-destructive" role="alert">
              {fieldErrors.otp}
            </p>
          ) : (
             <p className="text-sm text-muted-foreground">
               Enter the 6-digit code we just sent to your email, or click the Magic Link in the email.
             </p>
          )}
        </div>

        <Button
          type="submit"
          size="cta"
          disabled={disabled || isSubmitting}
          className="w-full"
        >
          {isSubmitting ? (
            <><Loader2 className="h-5 w-5 animate-spin" /> Verifying...</>
          ) : (
            <><KeyRound className="h-5 w-5" /> Verify & Sign In</>
          )}
        </Button>

        <p className="text-center text-sm text-muted-foreground">
          <button
            type="button"
            onClick={() => {
              setOtpSent(false);
              setOtp("");
              onError?.(null);
            }}
            disabled={disabled || isSubmitting}
            className="font-semibold text-primary underline-offset-4 hover:underline disabled:opacity-50"
          >
            Use a different email
          </button>
        </p>
      </form>
    );
  }

  // Render Main Auth Form (Password Sign-in / Sign-up OR Email OTP Sender)
  return (
    <div className="space-y-6">
      <form onSubmit={mode === "otp" ? handleSendOtp : handlePasswordAuth} className="space-y-4" noValidate>
        
        {/* Email Input is always visible */}
        <div className="space-y-2">
          <Label htmlFor="email-auth-email">Email address</Label>
          <Input
            id="email-auth-email"
            type="email"
            name="email"
            autoComplete="email"
            inputMode="email"
            placeholder="you@example.com"
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            disabled={disabled || isSubmitting}
            aria-invalid={Boolean(fieldErrors.email)}
          />
          {fieldErrors.email && (
            <p className="text-sm text-destructive" role="alert">{fieldErrors.email}</p>
          )}
        </div>

        {/* Password Inputs (Only if mode is sign-in or sign-up) */}
        {mode !== "otp" && (
          <>
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label htmlFor="email-auth-password">Password</Label>
                {mode === "sign-in" && (
                  <button
                    type="button"
                    disabled={isSubmitting}
                    onClick={handleForgotPassword}
                    className="text-xs font-medium text-primary hover:underline disabled:opacity-50"
                  >
                    {isSubmitting ? "Sending..." : "Forgot password?"}
                  </button>
                )}
              </div>
              <Input
                id="email-auth-password"
                type="password"
                name="password"
                autoComplete={mode === "sign-in" ? "current-password" : "new-password"}
                placeholder="••••••••"
                value={password}
                onChange={(event) => setPassword(event.target.value)}
                disabled={disabled || isSubmitting}
                aria-invalid={Boolean(fieldErrors.password)}
              />
              {fieldErrors.password && (
                <p className="text-sm text-destructive" role="alert">{fieldErrors.password}</p>
              )}
            </div>

            {mode === "sign-up" && (
              <div className="space-y-2">
                <Label htmlFor="email-auth-confirm-password">Confirm Password</Label>
                <Input
                  id="email-auth-confirm-password"
                  type="password"
                  name="confirmPassword"
                  autoComplete="new-password"
                  placeholder="••••••••"
                  value={confirmPassword}
                  onChange={(event) => setConfirmPassword(event.target.value)}
                  disabled={disabled || isSubmitting}
                  aria-invalid={Boolean(fieldErrors.confirmPassword)}
                />
                {fieldErrors.confirmPassword && (
                  <p className="text-sm text-destructive" role="alert">{fieldErrors.confirmPassword}</p>
                )}
              </div>
            )}
          </>
        )}

        {/* Submit Button */}
        <Button
          type="submit"
          size="cta"
          disabled={disabled || isSubmitting}
          className="w-full"
        >
          {isSubmitting ? (
            <><Loader2 className="h-5 w-5 animate-spin" /> Please wait...</>
          ) : mode === "otp" ? (
            <><Mail className="h-5 w-5" /> Send Code <ArrowRight className="h-5 w-5 transition-transform group-hover/button:translate-x-0.5" /></>
          ) : mode === "sign-in" ? (
            <><KeyRound className="h-5 w-5" /> Sign In <ArrowRight className="h-5 w-5 transition-transform group-hover/button:translate-x-0.5" /></>
          ) : (
            <><Lock className="h-5 w-5" /> Create Account <ArrowRight className="h-5 w-5 transition-transform group-hover/button:translate-x-0.5" /></>
          )}
        </Button>
      </form>

      {/* Mode Switchers */}
      <div className="flex flex-col items-center gap-3 pt-2">
        {mode === "otp" ? (
          <button
            type="button"
            onClick={() => { setMode("sign-in"); onError?.(null); }}
            className="text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
          >
            I want to use my password
          </button>
        ) : (
          <button
            type="button"
            onClick={() => { setMode("otp"); onError?.(null); }}
            className="text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
          >
            Sign in with a code or link instead
          </button>
        )}

        <div className="h-px w-full max-w-[200px] bg-border my-2" />

        <div className="text-sm">
          {mode === "sign-in" ? (
            <span className="text-muted-foreground">
              Don't have an account?{" "}
              <button 
                type="button"
                onClick={() => { setMode("sign-up"); onError?.(null); }}
                className="font-semibold text-primary hover:underline"
              >
                Sign up
              </button>
            </span>
          ) : mode === "sign-up" ? (
            <span className="text-muted-foreground">
              Already have an account?{" "}
              <button 
                type="button"
                onClick={() => { setMode("sign-in"); onError?.(null); }}
                className="font-semibold text-primary hover:underline"
              >
                Sign in
              </button>
            </span>
          ) : null}
        </div>
      </div>
    </div>
  );
}

export default EmailAuthForm;

"use client";

import { useEffect, useState, useRef, useMemo } from "react";
import { createClient } from "@/lib/supabase/client";
import { sendMessage, getMessages } from "@/app/actions/chat";
import { Send, Loader2, Lock, CheckCheck, ChevronLeft } from "lucide-react";
import Link from "next/link";
import { toast } from "sonner";

type Message = {
  id: string;
  lead_id: string;
  sender_user_id: string;
  body: string;
  created_at: string;
};

interface ChatInterfaceProps {
  leadId: string;
  currentUserId: string;
  vendorUserIds?: string[];
  initialMessages: Message[];
  otherPartyName: string;
  backLink?: string;
  headerActions?: React.ReactNode;
}

function getInitials(name: string) {
  return name
    .split(" ")
    .map((n) => n[0])
    .slice(0, 2)
    .join("")
    .toUpperCase() || "?";
}

function formatTime(dateString: string) {
  return new Date(dateString).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

function isSameDay(date1: string, date2: string) {
  const d1 = new Date(date1);
  const d2 = new Date(date2);
  return (
    d1.getFullYear() === d2.getFullYear() &&
    d1.getMonth() === d2.getMonth() &&
    d1.getDate() === d2.getDate()
  );
}

function formatDateLabel(dateString: string) {
  const date = new Date(dateString);
  const today = new Date();
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);

  if (isSameDay(dateString, today.toISOString())) {
    return "Today";
  } else if (isSameDay(dateString, yesterday.toISOString())) {
    return "Yesterday";
  } else {
    return date.toLocaleDateString([], { weekday: 'long', month: 'short', day: 'numeric' });
  }
}

// Subtle chat background pattern
const ChatBg = () => (
  <svg className="absolute inset-0 w-full h-full opacity-[0.06]" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <pattern id="chat-dots" x="0" y="0" width="24" height="24" patternUnits="userSpaceOnUse">
        <circle cx="12" cy="12" r="1.5" fill="#94a3b8" />
      </pattern>
    </defs>
    <rect width="100%" height="100%" fill="url(#chat-dots)" />
  </svg>
);

export function ChatInterface({ leadId, currentUserId, vendorUserIds, initialMessages, otherPartyName, backLink, headerActions }: ChatInterfaceProps) {
  const [messages, setMessages] = useState<Message[]>(initialMessages);
  const [newMessage, setNewMessage] = useState("");
  const [isSending, setIsSending] = useState(false);
  const [pendingMessageIds, setPendingMessageIds] = useState<Set<string>>(new Set());
  
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  
  const [supabase] = useState(() => createClient());

  const isVendorMember = useMemo(() => vendorUserIds?.includes(currentUserId) ?? false, [vendorUserIds, currentUserId]);

  const groupedMessages = useMemo(() => {
    const groups: { dateLabel: string; messages: (Message & { isConsecutive: boolean; isLastInGroup: boolean })[] }[] = [];
    
    messages.forEach((msg, index) => {
      const dateLabel = formatDateLabel(msg.created_at);
      let group = groups.find((g) => g.dateLabel === dateLabel);
      if (!group) {
        group = { dateLabel, messages: [] };
        groups.push(group);
      }

      const prevMsg = index > 0 ? messages[index - 1] : null;
      const nextMsg = index < messages.length - 1 ? messages[index + 1] : null;

      const isConsecutive = prevMsg ? prevMsg.sender_user_id === msg.sender_user_id && isSameDay(prevMsg.created_at, msg.created_at) : false;
      const isLastInGroup = !nextMsg || nextMsg.sender_user_id !== msg.sender_user_id || !isSameDay(msg.created_at, nextMsg.created_at);

      group.messages.push({ ...msg, isConsecutive, isLastInGroup });
    });

    return groups;
  }, [messages]);

  const scrollToBottom = (force = false) => {
    if (!scrollContainerRef.current || !messagesEndRef.current) return;
    const { scrollTop, scrollHeight, clientHeight } = scrollContainerRef.current;
    if (force || scrollHeight - scrollTop - clientHeight < 200) {
      messagesEndRef.current.scrollIntoView({ behavior: "smooth" });
    }
  };

  useEffect(() => { scrollToBottom(); }, [messages]);

  useEffect(() => {
    const channel = supabase
      .channel(`chat_${leadId}`)
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "messages", filter: `lead_id=eq.${leadId}` },
        (payload) => {
          const newMsg = payload.new as Message;
          setMessages((prev) => {
            if (prev.find((m) => m.id === newMsg.id)) return prev;
            return [...prev, newMsg];
          });
        }
      )
      .subscribe();

    const interval = setInterval(async () => {
      try {
        const { data } = await getMessages(leadId);
        if (data && Array.isArray(data)) {
          setMessages((prev) => {
            const realPrevMessages = prev.filter(m => !m.id.startsWith('temp-'));
            const tempMessages = prev.filter(m => m.id.startsWith('temp-'));
            if (realPrevMessages.length !== data.length) {
              return [...data, ...tempMessages];
            }
            return prev;
          });
        }
      } catch (err) {
        // ignore polling errors
      }
    }, 4000);

    return () => { 
      supabase.removeChannel(channel); 
      clearInterval(interval);
    };
  }, [leadId, supabase]);

  const handleSend = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!newMessage.trim() || isSending) return;

    const tempBody = newMessage.trim();
    const tempId = `temp-${Date.now()}`;
    
    setNewMessage(""); 
    if (textareaRef.current) textareaRef.current.style.height = "auto";
    
    const optimisticMessage: Message = {
      id: tempId,
      lead_id: leadId,
      sender_user_id: currentUserId,
      body: tempBody,
      created_at: new Date().toISOString(),
    };
    
    setMessages((prev) => [...prev, optimisticMessage]);
    setPendingMessageIds((prev) => new Set(prev).add(tempId));
    setIsSending(true);
    
    setTimeout(() => scrollToBottom(true), 50);

    try {
      const { data, error } = await sendMessage(leadId, tempBody);
      if (error) {
        toast.error(error);
        setNewMessage(tempBody);
        setMessages((prev) => prev.filter(m => m.id !== tempId));
      } else if (data) {
        setMessages((prev) => prev.map(m => m.id === tempId ? data : m));
      }
    } finally {
      setIsSending(false);
      setPendingMessageIds((prev) => {
        const next = new Set(prev);
        next.delete(tempId);
        return next;
      });
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setNewMessage(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = `${Math.min(e.target.scrollHeight, 160)}px`;
  };

  const otherInitials = getInitials(otherPartyName);

  return (
    <div className="fixed inset-0 z-50 md:relative md:inset-auto md:z-auto flex flex-col h-[100dvh] md:h-full w-full overflow-hidden">
      
      {/* Premium Header */}
      <div className="bg-white border-b border-slate-100 px-4 sm:px-5 py-3 flex items-center justify-between z-20 flex-shrink-0">
        <div className="flex items-center gap-3">
          {backLink && (
            <Link href={backLink} className="md:hidden -ml-1 p-2 rounded-xl hover:bg-slate-100 text-slate-600 transition-all active:scale-95">
              <ChevronLeft className="h-5 w-5" />
            </Link>
          )}
          {/* Rounded-square avatar */}
          <div className="relative shrink-0">
            <div className="h-10 w-10 rounded-[10px] bg-gradient-to-br from-primary to-[#c2410c] flex items-center justify-center text-white font-extrabold text-sm shadow-[0_3px_10px_rgba(234,88,12,0.3)]">
              {otherInitials}
            </div>
            <div className="absolute -bottom-0.5 -right-0.5 h-3 w-3 rounded-full bg-emerald-500 border-2 border-white shadow-sm" />
          </div>
          <div>
            <div className="font-semibold text-slate-900 text-[15px] leading-tight tracking-tight">{otherPartyName}</div>
            <p className="text-[11px] text-emerald-600 font-semibold mt-0.5">● Online · Replies quickly</p>
          </div>
        </div>
        
        {/* Right actions */}
        <div className="flex items-center gap-2">
          {headerActions}
        </div>
      </div>

      {/* Messages Area with subtle pattern */}
      <div className="flex-1 overflow-hidden relative bg-slate-50">
        <ChatBg />
        <div 
          ref={scrollContainerRef} 
          className="absolute inset-0 overflow-y-auto px-4 sm:px-6 py-5 flex flex-col scroll-smooth"
          style={{ scrollbarWidth: 'thin', scrollbarColor: '#cbd5e1 transparent' }}
        >
          {/* Encryption notice */}
          <div className="flex justify-center mb-8">
            <div className="flex items-center gap-1.5 bg-white/80 border border-slate-200/60 backdrop-blur-sm px-4 py-2 rounded-full shadow-sm">
              <Lock className="h-3 w-3 text-slate-400 shrink-0" />
              <span className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider">End-to-end encrypted</span>
            </div>
          </div>

          {messages.length === 0 ? (
            <div className="flex-1 flex flex-col items-center justify-center gap-5 py-16">
              <div className="relative">
                <div className="h-24 w-24 rounded-3xl bg-white shadow-[0_8px_30px_rgba(0,0,0,0.06)] flex items-center justify-center">
                  <div className="h-16 w-16 rounded-2xl bg-gradient-to-br from-primary/10 to-primary/20 flex items-center justify-center">
                    <Send className="h-7 w-7 text-primary translate-x-0.5" />
                  </div>
                </div>
              </div>
              <div className="text-center">
                <h3 className="font-heading font-bold text-slate-800 text-lg">Start the conversation</h3>
                <p className="text-slate-500 text-sm mt-1.5 max-w-[200px] leading-relaxed">Send a message to connect with {otherPartyName}</p>
              </div>
            </div>
          ) : (
            <div className="flex flex-col flex-1 justify-end gap-0">
              {groupedMessages.map((group) => (
                <div key={group.dateLabel} className="flex flex-col w-full mb-6">
                  {/* Date separator */}
                  <div className="flex items-center justify-center mb-5">
                    <div className="bg-white/90 border border-slate-200/60 backdrop-blur-sm shadow-sm px-4 py-1.5 rounded-full">
                      <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                        {group.dateLabel}
                      </span>
                    </div>
                  </div>

                  {/* Messages */}
                  <div className="flex flex-col gap-0.5">
                    {group.messages.map((msg) => {
                      const isMe = isVendorMember 
                        ? vendorUserIds!.includes(msg.sender_user_id) 
                        : msg.sender_user_id === currentUserId;
                      const isPending = pendingMessageIds.has(msg.id);
                      
                      return (
                        <div 
                          key={msg.id} 
                          className={`
                            flex w-full items-end gap-2
                            ${isMe ? "justify-end" : "justify-start"}
                            ${!msg.isConsecutive ? "mt-5" : "mt-0.5"}
                          `}
                        >
                          {/* Other person's avatar */}
                          {!isMe && (
                            <div className="shrink-0 self-end mb-1">
                              {msg.isLastInGroup ? (
                                <div className="h-7 w-7 rounded-xl bg-gradient-to-br from-slate-100 to-slate-200 border border-white shadow-sm flex items-center justify-center text-slate-600 font-bold text-[10px]">
                                  {otherInitials}
                                </div>
                              ) : (
                                <div className="w-7" />
                              )}
                            </div>
                          )}

                          {/* Message bubble */}
                          <div className={`
                            flex flex-col max-w-[78%] sm:max-w-[65%]
                            ${isMe ? "items-end" : "items-start"}
                          `}>
                            <div className={`
                              px-4 py-2.5 text-[14px] leading-[1.5] break-words whitespace-pre-wrap
                              transition-all duration-200
                              ${isPending ? "opacity-60" : "opacity-100"}
                              ${isMe 
                                ? `bg-primary text-white font-medium
                                   ${msg.isConsecutive && msg.isLastInGroup ? "rounded-l-2xl rounded-tr-md rounded-br-2xl"
                                     : !msg.isConsecutive && !msg.isLastInGroup ? "rounded-l-2xl rounded-t-2xl rounded-br-md"
                                     : msg.isConsecutive && !msg.isLastInGroup ? "rounded-l-2xl rounded-r-md"
                                     : "rounded-2xl rounded-br-md"
                                   }
                                   shadow-[0_2px_8px_rgba(234,88,12,0.2)]`
                                : `bg-white text-slate-800
                                   ${msg.isConsecutive && msg.isLastInGroup ? "rounded-r-2xl rounded-tl-md rounded-bl-2xl"
                                     : !msg.isConsecutive && !msg.isLastInGroup ? "rounded-r-2xl rounded-t-2xl rounded-bl-md"
                                     : msg.isConsecutive && !msg.isLastInGroup ? "rounded-r-2xl rounded-l-md"
                                     : "rounded-2xl rounded-bl-md"
                                   }
                                   border border-slate-100 shadow-[0_1px_4px_rgba(0,0,0,0.04)]`
                              }
                            `}>
                              {msg.body}
                            </div>
                            
                            {/* Time + status */}
                            {msg.isLastInGroup && (
                              <div className={`flex items-center gap-1 mt-1.5 px-1 ${isMe ? 'flex-row-reverse' : ''}`}>
                                <span className="text-[10px] text-slate-400 font-semibold">
                                  {formatTime(msg.created_at)}
                                </span>
                                {isMe && (
                                  isPending 
                                    ? <Loader2 className="h-3 w-3 text-slate-400 animate-spin" />
                                    : <CheckCheck className="h-3.5 w-3.5 text-primary" />
                                )}
                              </div>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          )}
          <div ref={messagesEndRef} className="h-2 shrink-0" />
        </div>
      </div>

      {/* Input Area */}
      <div className="bg-white border-t border-slate-100 px-4 sm:px-5 py-3.5 z-20 flex-shrink-0">
        <form onSubmit={handleSend} className="flex items-end gap-3 max-w-4xl mx-auto">
          {/* Textarea wrapper */}
          <div className="flex-1 bg-slate-50 border border-slate-200 rounded-2xl focus-within:bg-white focus-within:border-primary/40 focus-within:ring-4 focus-within:ring-primary/[0.08] transition-all duration-200">
            <textarea
              ref={textareaRef}
              value={newMessage}
              onChange={handleInput}
              onKeyDown={handleKeyDown}
              placeholder="Message..."
              rows={1}
              className="w-full resize-none bg-transparent px-4 py-3 text-base md:text-[14px] text-slate-800 placeholder:text-slate-400 focus:outline-none leading-relaxed max-h-[160px] font-medium"
              disabled={isSending}
              style={{ minHeight: '46px' }}
            />
          </div>

          {/* Send button */}
          <button
            type="submit"
            disabled={!newMessage.trim() || isSending}
            className="
              flex h-[46px] w-[46px] shrink-0 items-center justify-center
              rounded-2xl bg-primary text-white
              hover:bg-[#c2410c] hover:shadow-[0_4px_16px_rgba(234,88,12,0.35)]
              active:scale-95
              disabled:opacity-40 disabled:hover:shadow-none disabled:hover:bg-primary disabled:active:scale-100
              transition-all duration-200 shadow-[0_2px_8px_rgba(234,88,12,0.2)]
            "
            aria-label="Send message"
          >
            {isSending ? (
              <Loader2 className="h-4.5 w-4.5 animate-spin" />
            ) : (
