import { optionalEnv } from "@/lib/config";
import { createAdminClient } from "@/lib/supabase/admin";

export interface BlogPreflightResult {
  ready: boolean;
  checks: {
    id: string;
    label: string;
    ok: boolean;
    detail: string;
  }[];
}

export async function runBlogPreflight(): Promise<BlogPreflightResult> {
  const checks: BlogPreflightResult["checks"] = [];

  const geminiKey = optionalEnv("GEMINI_API_KEY");
  checks.push({
    id: "gemini",
    label: "GEMINI_API_KEY",
    ok: !!geminiKey,
    detail: geminiKey ? "Configured" : "Missing — article generation will fail",
  });

  const cronSecret = optionalEnv("CRON_SECRET");
  checks.push({
    id: "cron",
    label: "CRON_SECRET",
    ok: !!cronSecret && cronSecret.length >= 16 && !/\s/.test(cronSecret),
    detail: cronSecret
      ? cronSecret.length >= 16 && !/\s/.test(cronSecret)
        ? "Configured"
        : "Must be 16+ chars with no spaces/newlines"
      : "Missing — Vercel cron cannot authenticate",
  });

  const unsplash = optionalEnv("UNSPLASH_ACCESS_KEY");
  checks.push({
    id: "unsplash",
    label: "UNSPLASH_ACCESS_KEY",
    ok: !!unsplash,
    detail: unsplash
      ? "Configured (image fallback)"
      : "Optional — recommended if Imagen fails",
  });

  let dbOk = false;
  let categoryCount = 0;
  let bucketOk = false;

  try {
    const supabase = createAdminClient();

    const { error: tableError } = await supabase
      .from("blog_articles")
      .select("id", { count: "exact", head: true });

    dbOk = !tableError;
    checks.push({
      id: "db",
      label: "Database tables",
      ok: dbOk,
      detail: tableError
        ? `blog_articles missing — run migration 20260618100000_blog_articles.sql (${tableError.message})`
        : "blog_articles table exists",
    });

    if (dbOk) {
      const { count } = await supabase
        .from("blog_categories")
        .select("id", { count: "exact", head: true });
      categoryCount = count ?? 0;
      checks.push({
        id: "categories",
        label: "Blog categories",
        ok: categoryCount > 0,
        detail:
          categoryCount > 0
            ? `${categoryCount} categories seeded`
            : "No categories — re-run migration seed",
      });
    }

    const { data: buckets } = await supabase.storage.listBuckets();
    bucketOk = buckets?.some((b) => b.name === "blog-images") ?? false;
    checks.push({
      id: "storage",
      label: "blog-images bucket",
      ok: bucketOk,
      detail: bucketOk
        ? "Storage bucket exists"
        : "Missing — featured image uploads will fail",
    });
  } catch (err) {
    checks.push({
      id: "db",
      label: "Database tables",
      ok: false,
      detail: err instanceof Error ? err.message : "Database unreachable",
    });
  }

  const requiredOk = checks
    .filter((c) => c.id !== "unsplash")
    .every((c) => c.ok || (c.id === "storage" && dbOk)); // storage nice-to-have for publish without image

  // Required: gemini, cron (for auto), db, categories
  const ready =
    !!geminiKey &&
    dbOk &&
    categoryCount > 0 &&
    (!!cronSecret || true); // cron only needed for automated runs, not manual admin trigger

  return {
    ready: !!geminiKey && dbOk && categoryCount > 0,
    checks,
  };
}

import { cache } from "react";
import { createAdminClient } from "@/lib/supabase/admin";

export type VendorContext = {
  setupError?: string;
  organizations: Array<{
    id: string;
    name: string;
    slug: string;
    status: string;
    abn: string;
    branches: Array<{
      id: string;
      name: string;
      city: string;
      state: string;
      address: string;
      status: string;
      phone: string | null;
      whatsapp: string | null;
    }>;
  }>;
};

export type VehicleLimitInfo = {
  currentCount: number;
  limit: number | null;
  hasLimit: boolean;
  canAddMore: boolean;
  planCode: string | null;
};

export async function getVehicleLimitInfo(organizationId: string): Promise<VehicleLimitInfo> {
  const supabase = createAdminClient();

  const [countResult, subResult] = await Promise.all([
    supabase.from("vehicles").select("id", { count: "exact", head: true }).eq("organization_id", organizationId),
    supabase.from("subscriptions").select("plan_code, status").eq("organization_id", organizationId).eq("status", "active").maybeSingle(),
  ]);

  if (countResult.error) {
    throw new Error(`Failed to count vehicles: ${countResult.error.message}`);
  }

  if (subResult.error) {
    throw new Error(`Failed to get subscription: ${subResult.error.message}`);
  }

  const currentCount = countResult.count;
  const subscription = subResult.data;

  // If no active subscription, check for trialing
  let planCode = subscription?.plan_code;
  if (!planCode) {
    const { data: trialing } = await supabase
      .from("subscriptions")
      .select("plan_code")
      .eq("organization_id", organizationId)
      .eq("status", "trialing")
      .maybeSingle();
    planCode = trialing?.plan_code;
  }

  // Get plan limit
  let limit: number | null = null;
  if (planCode) {
    const { data: plan } = await supabase
      .from("plans")
      .select("vehicle_limit")
      .eq("code", planCode)
      .single();
    limit = plan?.vehicle_limit ?? null;
  } else {
    // If there is no active or trialing plan, the limit is strictly 0.
    limit = 0;
  }

  // null limit means unlimited (enterprise/business plans)
  const hasLimit = limit !== null;
  const canAddMore = !hasLimit || (currentCount ?? 0) < (limit ?? 0);

  return {
    currentCount: currentCount ?? 0,
    limit,
    hasLimit,
    canAddMore,
    planCode: planCode ?? null,
  };
}

export async function enforceVehicleLimit(organizationId: string): Promise<void> {
  const limitInfo = await getVehicleLimitInfo(organizationId);

  if (!limitInfo.canAddMore) {
    throw new Error(
      `Vehicle limit reached. Your ${limitInfo.planCode} plan allows ${limitInfo.limit} vehicles. ` +
        `Please upgrade your plan to add more vehicles.`,
    );
  }
}

export const getVendorContext = cache(async function getVendorContext(userId: string): Promise<VendorContext> {
  const supabase = createAdminClient();

  const { data: memberships, error } = await supabase
    .from("organization_members")
    .select("organization_id, role")
    .eq("user_id", userId);

  if (error) {
    return {
      organizations: [],
      setupError:
        "Database tables are not available yet. Apply the Supabase migration before using vendor workflows.",
    };
  }

  const organizationIds = memberships?.map((item) => item.organization_id) ?? [];

  if (organizationIds.length === 0) {
    return { organizations: [] };
  }

  const [orgResult, branchResult] = await Promise.all([
    supabase
      .from("organizations")
      .select("id, name, slug, status, abn")
      .in("id", organizationIds)
      .order("created_at", { ascending: true }),
    supabase
      .from("branches")
      .select("id, organization_id, name, city, state, address, status, phone, whatsapp")
      .in("organization_id", organizationIds)
      .order("created_at", { ascending: true }),
  ]);

  if (orgResult.error || branchResult.error) {
    console.error("Organizations fetch error:", orgResult.error);
    console.error("Branches fetch error:", branchResult.error);
    return {
      organizations: [],
      setupError: "Failed to load vendor data. Please try again or contact support."
    };
  }

  const organizations = orgResult.data;
  const branches = branchResult.data;

  return {
    organizations:
      organizations?.map((organization) => ({
        ...organization,
        branches:
          (branches || [])
            .filter((branch) => branch.organization_id === organization.id)
            .map((branch) => ({
              id: branch.id,
              name: branch.name,
              city: branch.city,
              state: branch.state,
              address: branch.address,
              status: branch.status,
              phone: branch.phone,
              whatsapp: branch.whatsapp,
            })),
      })) ?? [],
  };
});

export async function ensureUserCanManageOrganization(
  userId: string,
  organizationId: string,
) {
  const supabase = createAdminClient();
  const { data, error } = await supabase
    .from("organization_members")
    .select("role")
    .eq("user_id", userId)
    .eq("organization_id", organizationId)
    .in("role", ["owner", "admin", "manager"])
    .maybeSingle();

  if (error || !data) {
    throw new Error("You do not have permission to manage this organization.");
  }
}

export type LeadWithVehicle = {
  id: string;
  vehicleId: string;
  vehicleTitle: string;
  customerName: string;
  customerEmail: string;
  customerPhone: string;
  pickupCity: string;
  startDate: string;
  endDate: string;
  message: string | null;
  status: "new" | "contacted" | "converted" | "lost";
  createdAt: string;
  events: Array<{
    id: string;
    eventType: string;
    createdAt: string;
    actorName?: string;
  }>;
};

export async function getOrganizationLeads(
  organizationId: string,
  userId: string,
  options: {
    status?: "new" | "contacted" | "converted" | "lost";
    limit?: number;
    offset?: number;
  } = {},
): Promise<{ leads: LeadWithVehicle[]; total: number }> {
  await ensureUserCanManageOrganization(userId, organizationId);

  const supabase = createAdminClient();
  const { status, limit = 50, offset = 0 } = options;

  let query = supabase
    .from("leads")
    .select(
      `
      id,
      vehicle_id,
      vehicles(title),
      customer_name,
      customer_email,
      customer_phone,
      pickup_city,
      start_date,
      end_date,
      message,
      status,
      created_at,
      lead_events(id, event_type, created_at, profiles(full_name))
    `,
      { count: "exact" },
    )
    .eq("vendor_id", organizationId)
    .order("created_at", { ascending: false })
    .range(offset, offset + limit - 1);

  if (status) {
    query = query.eq("status", status);
  }

  const { data, error, count } = await query;

  if (error) {
    throw new Error(`Failed to fetch leads: ${error.message}`);
  }

  const leads: LeadWithVehicle[] =
    data?.map((lead) => {
      const vehicle = lead.vehicles as unknown as { title: string } | null;
      const events = (lead.lead_events as unknown as Array<{
        id: string;
        event_type: string;
        created_at: string;
        profiles: { full_name: string } | null;
      }>) ?? [];

      return {
        id: lead.id,
        vehicleId: lead.vehicle_id,
        vehicleTitle: vehicle?.title ?? "Unknown Vehicle",
        customerName: lead.customer_name,
        customerEmail: lead.customer_email,
        customerPhone: lead.customer_phone,
        pickupCity: lead.pickup_city,
        startDate: lead.start_date,
        endDate: lead.end_date,
        message: lead.message,
        status: lead.status as LeadWithVehicle["status"],
        createdAt: lead.created_at,
        events: events.map((e) => ({
          id: e.id,
          eventType: e.event_type,
          createdAt: e.created_at,
          actorName: e.profiles?.full_name ?? undefined,
        })),
      };
    }) ?? [];

  return { leads, total: count ?? 0 };
}

export async function getLeadStats(organizationId: string, userId: string) {
  await ensureUserCanManageOrganization(userId, organizationId);

  const supabase = createAdminClient();

  const { data, error } = await supabase
    .from("leads")
    .select("status")
    .eq("vendor_id", organizationId);

  if (error) {
    throw new Error(`Failed to fetch lead stats: ${error.message}`);
  }

  const stats = {
    total: data?.length ?? 0,
    new: data?.filter((l) => l.status === "new").length ?? 0,
    contacted: data?.filter((l) => l.status === "contacted").length ?? 0,
    converted: data?.filter((l) => l.status === "converted").length ?? 0,
    lost: data?.filter((l) => l.status === "lost").length ?? 0,
  };

  return stats;
}

export type DashboardMetrics = {
  vehicleCount: number;
  activeListings: number;
  pendingListings: number;
  newLeads: number;
  totalLeads: number;
  planLimit: number | null;
  planCode: string | null;
  planUsage: string;
  branchCount: number;
  clickStats: {
    phone: number;
    whatsapp: number;
    total: number;
  };
  totalViews: number;
};

export async function getDashboardMetrics(
  organizationId: string,
  userId: string,
): Promise<DashboardMetrics> {
  await ensureUserCanManageOrganization(userId, organizationId);

  const supabase = createAdminClient();
  const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();

  const [
    metricsRes,
    limitInfo,
    branchRes,
  ] = await Promise.all([
    supabase.rpc("get_vendor_dashboard_metrics", { org_id: organizationId }).single(),
    getVehicleLimitInfo(organizationId),
    supabase.from("branches").select("id", { count: "exact", head: true }).eq("organization_id", organizationId),
  ]);

  if (metricsRes.error) throw new Error(`Failed to fetch metrics: ${metricsRes.error.message}`);
  if (branchRes.error) throw new Error(`Failed to fetch branches: ${branchRes.error.message}`);

  const metrics = metricsRes.data as {
    total_views: number;
    active_listings: number;
    pending_listings: number;
    total_vehicles: number;
    new_leads: number;
    total_leads: number;
    phone_clicks_30d: number;
    whatsapp_clicks_30d: number;
    total_clicks_30d: number;
  };
  const branchCount = branchRes.count;

  return {
    vehicleCount: metrics.total_vehicles,
    activeListings: metrics.active_listings,
    pendingListings: metrics.pending_listings,
    newLeads: metrics.new_leads,
    totalLeads: metrics.total_leads,
    planLimit: limitInfo.limit,
    planCode: limitInfo.planCode,
    planUsage: limitInfo.hasLimit
      ? `${limitInfo.currentCount} / ${limitInfo.limit}`
      : `${limitInfo.currentCount} / ∞`,
    branchCount: branchCount ?? 0,
    clickStats: {
      phone: metrics.phone_clicks_30d,
      whatsapp: metrics.whatsapp_clicks_30d,
      total: metrics.total_clicks_30d,
    },
    totalViews: metrics.total_views,
  };
}

/**
 * image-utils.ts
 *
 * Single source of truth for resolving a vehicle image URL from Supabase Storage.
 *
 * The system uses TWO storage buckets:
 *   "vehicle-images"         — public  — images uploaded by APPROVED orgs   (approved=true)
 *   "pending-vehicle-images" — private — images uploaded by PENDING  orgs   (approved=false)
 *
 * getPublicUrl() on the PRIVATE bucket returns a URL that always 404s for public users.
 * This helper always routes to the correct bucket based on the `approved` flag.
 *
 * Priority order when resolving a fallback:
 *   1. Category-specific Unsplash stock photo (relevant visuals, never broken)
 *   2. Generic car placeholder
 */

/** Minimal image record returned from vehicle_images join */
export type VehicleImageRecord = {
  storage_path: string;
  approved: boolean;
  sort_order: number;
};

/** Category → stock photo fallback */
const CATEGORY_PLACEHOLDERS: Record<string, string> = {
  Sedan:         "https://images.unsplash.com/photo-1549317661-bd32c8ce0db2?auto=format&fit=crop&w=800&q=80",
  SUV:           "https://images.unsplash.com/photo-1519641471654-76ce0107ad1b?auto=format&fit=crop&w=800&q=80",
  Van:           "https://images.unsplash.com/photo-1559416523-140ddc3d238c?auto=format&fit=crop&w=800&q=80",
  Ute:           "https://images.unsplash.com/photo-1533473359331-0135ef1b58bf?auto=format&fit=crop&w=800&q=80",
  Luxury:        "https://images.unsplash.com/photo-1563720223185-11003d516935?auto=format&fit=crop&w=800&q=80",
  "People mover":"https://images.unsplash.com/photo-1503376780353-7e6692767b70?auto=format&fit=crop&w=800&q=80",
  Truck:         "https://images.unsplash.com/photo-1601584115197-04ecc0da31d7?auto=format&fit=crop&w=800&q=80",
  Electric:      "https://images.unsplash.com/photo-1560958089-b8a1929cea89?auto=format&fit=crop&w=800&q=80",
  Hatchback:     "https://images.unsplash.com/photo-1542282088-fe8426682b8f?auto=format&fit=crop&w=800&q=80",
};

const GENERIC_PLACEHOLDER =
  "https://images.unsplash.com/photo-1549317661-bd32c8ce0db2?auto=format&fit=crop&w=800&q=80";

/** Return an appropriate fallback for a category (never a broken URL). */
export function getCategoryFallback(category?: string | null): string {
  return (category && CATEGORY_PLACEHOLDERS[category]) ?? GENERIC_PLACEHOLDER;
}

/**
 * Build a Supabase Storage public URL for a vehicle_images row.
 *
 * @param supabaseUrl  process.env.NEXT_PUBLIC_SUPABASE_URL
 * @param img          A row from vehicle_images (needs storage_path + approved)
 */
export function buildStorageUrl(supabaseUrl: string, img: VehicleImageRecord): string {
  const bucket = img.approved ? "vehicle-images" : "pending-vehicle-images";
  // Construct direct public URL — avoids instantiating a Supabase client just for this
  return `${supabaseUrl}/storage/v1/object/public/${bucket}/${img.storage_path}`;
}

/**
 * Resolve the best displayable image URL for a vehicle given a list of
 * vehicle_images rows (already fetched from Supabase).
 *
 * Preference order:
 *   1. First approved image (lowest sort_order)
 *   2. First any image (lowest sort_order)  — so pending-org images still show
 *   3. Category stock photo fallback
 *
 * @param supabaseUrl   process.env.NEXT_PUBLIC_SUPABASE_URL
 * @param images        Rows from vehicle_images join
 * @param category      Vehicle category for fallback selection
 */
export function resolveVehicleImage(
  supabaseUrl: string,
  images: VehicleImageRecord[] | null | undefined,
  category?: string | null,
): string {
  if (!images || images.length === 0) {
    return getCategoryFallback(category);
  }

  const sorted = [...images].sort((a, b) => a.sort_order - b.sort_order);
  // Prefer approved (public bucket) first; fall back to any image
  const best = sorted.find((img) => img.approved) ?? sorted[0];
  return buildStorageUrl(supabaseUrl, best);
}

/**
 * Resolve ALL images for the detail-page gallery.
 * Returns an array of { url, alt_text } objects ready for <ImageGallery>.
 *
 * @param supabaseUrl   process.env.NEXT_PUBLIC_SUPABASE_URL
 * @param images        Rows from vehicle_images join (must include alt_text)
 * @param vehicleTitle  Used for default alt text
 */
export type GalleryImage = {
  id: string;
  url: string;
  alt_text: string;
};

export type FullImageRecord = VehicleImageRecord & {
  id: string;
  alt_text: string | null;
};

export function resolveGalleryImages(
  supabaseUrl: string,
  images: FullImageRecord[] | null | undefined,
  vehicleTitle: string,
): GalleryImage[] {
  if (!images || images.length === 0) return [];

  return [...images]
    .sort((a, b) => a.sort_order - b.sort_order)
    .map((img) => ({
      id: img.id,
      url: buildStorageUrl(supabaseUrl, img),
      alt_text: img.alt_text || `${vehicleTitle} rental car image`,
    }));
}

/**
 * Resolves a list of GalleryImage objects for a vehicle.
 * Combines Supabase database images with standard and custom image fields,
 * and falls back to a category-specific stock photo placeholder if all fields are empty.
 */
export function getVehicleImages(vehicle: any): GalleryImage[] {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || "";
  const title = vehicle.title || "Rental Car";
  
  // 1. Collect from database vehicle_images relation
  const dbImages = (vehicle.vehicle_images as FullImageRecord[]) || [];
  const galleryImages = resolveGalleryImages(supabaseUrl, dbImages, title);
  
  // 2. Collect other potential custom/standard fields defensively
  const rawUrls: string[] = [];
  if (typeof vehicle.featuredImage === "string" && vehicle.featuredImage.trim()) {
    rawUrls.push(vehicle.featuredImage);
  }
  if (typeof vehicle.image === "string" && vehicle.image.trim()) {
    rawUrls.push(vehicle.image);
  }
  if (typeof vehicle.thumbnail === "string" && vehicle.thumbnail.trim()) {
    rawUrls.push(vehicle.thumbnail);
  }
  
  if (Array.isArray(vehicle.images)) {
    vehicle.images.forEach((img: any) => {
      if (typeof img === "string" && img.trim()) {
        rawUrls.push(img);
      } else if (img && typeof img.url === "string" && img.url.trim()) {
        rawUrls.push(img.url);
      }
    });
  }
  
  if (Array.isArray(vehicle.gallery)) {
    vehicle.gallery.forEach((img: any) => {
      if (typeof img === "string" && img.trim()) {
        rawUrls.push(img);
      } else if (img && typeof img.url === "string" && img.url.trim()) {
        rawUrls.push(img.url);
      }
    });
  }
  
  const customImages: GalleryImage[] = rawUrls.map((url, index) => ({
    id: `custom-img-${index}-${Date.now()}`,
    url,
    alt_text: `${title} rental car image`,
  }));
  
  const combined = [...galleryImages, ...customImages];
  
  // 3. Fallback to category stock photo if completely empty
  if (combined.length === 0) {
    const fallbackUrl = getCategoryFallback(vehicle.category);
    return [
      {
        id: "fallback-category-stock",
        url: fallbackUrl,
        alt_text: `${title} placeholder stock image`,
      },
    ];
  }
  
  return combined;
}

